import{_ as i,C as a,o as d,c as h,j as t,a as o,E as s,ag as l}from"./chunks/framework.HG0H2VLS.js";const v=JSON.parse('{"title":"ListingScreen","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/listing-screen.md","filePath":"cc-templates/listing-screen.md"}'),c={name:"cc-templates/listing-screen.md"},p={id:"listingscreen",tabindex:"-1"};function u(g,e,m,b,w,f){const n=a("Badge"),r=a("ComponentDemo");return d(),h("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-listingscreen",tabindex:"-1"},[o("title: ListingScreen "),t("a",{class:"header-anchor",href:"#title-listingscreen","aria-label":'Permalink to "title: ListingScreen"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=o("ListingScreen ",-1)),s(n,{type:"info",text:"Design System"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#listingscreen","aria-label":'Permalink to "ListingScreen <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,[o("the template behind "),t("strong",null,"~400 Control Centre screens"),o(", which differ only in datatable Type and default filter set")])],-1)),s(r,{src:"/demos/src/cc/templates/ListingScreen/ListingScreen.html"}),e[6]||(e[6]=l('<h2 id="why-this-template-exists" tabindex="-1">Why this template exists <a class="header-anchor" href="#why-this-template-exists" aria-label="Permalink to &quot;Why this template exists&quot;">​</a></h2><p>Roughly <strong>400 Control Centre screens</strong> are this one layout. They differ in only two things: which <strong>datatable Type</strong> renders, and which <strong>default filters</strong> show. Both are config (<code>listing-data.js</code>), not markup — so a new screen is a new config entry, not a new template.</p><h2 id="variant-matrix" tabindex="-1">Variant matrix <a class="header-anchor" href="#variant-matrix" aria-label="Permalink to &quot;Variant matrix&quot;">​</a></h2><p>The Listings page holds 19 screen frames in three rows. Pass 1 built row 1 only; the rest are the interaction set and are deliberately deferred (designer&#39;s scoping call, 2026-09-17 — &quot;build the screen … then we can work through all of the functionality&quot;).</p><table tabindex="0"><thead><tr><th>#</th><th>Screen</th><th>Desktop</th><th>Mobile</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td>Default</td><td><code>3645:148870</code></td><td><code>3648:161126</code></td><td><strong>Built</strong></td></tr><tr><td>2</td><td>Filter Active</td><td><code>3645:148871</code></td><td><code>3650:166012</code></td><td>Pass 2</td></tr><tr><td>3</td><td>Wrapping + Multiple Filters</td><td><code>3645:151046</code></td><td><code>3650:167527</code></td><td>Pass 2</td></tr><tr><td>4</td><td>View Dropdown</td><td><code>3645:153953</code></td><td><code>3650:168587</code></td><td>Pass 2</td></tr><tr><td>5</td><td>New View</td><td><code>3645:156799</code></td><td><code>3650:169668</code></td><td>Pass 2</td></tr><tr><td>6</td><td>Save View</td><td><code>3645:155718</code></td><td><code>3650:170677</code></td><td>Pass 2</td></tr><tr><td>7</td><td>Actions Menu</td><td><code>3645:157810</code></td><td><code>3650:171678</code></td><td>Pass 2</td></tr><tr><td>8</td><td>Datatable Expanded</td><td><code>3645:158905</code></td><td><code>3650:173002</code></td><td>Pass 2</td></tr><tr><td>9</td><td>Filter Dropdown / Text</td><td><code>3664:13374</code></td><td>—</td><td>Pass 2</td></tr><tr><td>10</td><td>Filter Dropdown / Select</td><td><code>3664:14458</code></td><td>—</td><td>Pass 2</td></tr><tr><td>11</td><td>Filter Dropdown / More Filters</td><td><code>3664:15491</code></td><td>—</td><td>Pass 2</td></tr></tbody></table><p>Note: much of rows 2–11 already exists in the <strong>FilterBar</strong> pattern, which was built from this same page. Pass 2 is finishing and wiring it, not building it cold.</p><h2 id="template-shell-—-paint-values-skill-step-3a" tabindex="-1">Template shell — paint values (skill Step 3a) <a class="header-anchor" href="#template-shell-—-paint-values-skill-step-3a" aria-label="Permalink to &quot;Template shell — paint values (skill Step 3a)&quot;">​</a></h2><p>Every value below traces to a <code>get_design_context</code> fetch, not to intuition.</p><table tabindex="0"><thead><tr><th>Wrapper</th><th>Property</th><th>Figma binding</th><th>Applied</th></tr></thead><tbody><tr><td>Page ground</td><td>background</td><td><code>--cc-ui-primary-bg</code></td><td><code>.cc-control__page</code> (ControlScreen, reused)</td></tr><tr><td>Page content</td><td>padding</td><td><code>--ai-spacing-6</code> (24px)</td><td><code>.cc-control__page</code> — already correct, not overridden</td></tr><tr><td>Content column (&quot;Frame 1&quot;)</td><td>flex-direction</td><td>column</td><td><code>.cc-listing</code></td></tr><tr><td>Content column</td><td>gap</td><td><code>--ai-spacing-4</code> (12px)</td><td><code>.cc-listing</code></td></tr><tr><td>Chrome — top nav</td><td>background</td><td><code>--cc-header-primary-bg</code></td><td>TopNavigation (reused)</td></tr><tr><td>Chrome — header band</td><td>background</td><td><code>--cc-header-secondary-bg</code></td><td><code>.cc-header</code> (reused)</td></tr><tr><td>Chrome — header band</td><td>min-height / padding</td><td><code>--ai-spacing-11</code> / <code>--ai-spacing-5</code></td><td><code>.cc-header</code> — already correct</td></tr><tr><td>Header title</td><td>font / size / tracking</td><td><code>--ai-font-title</code> bold · <code>--ai-font-fixed-xl</code> · <code>--ai-tracking-3</code></td><td><code>.cc-header__title</code> — already correct</td></tr></tbody></table><p>The shell is <strong>not forked</strong>. In Figma, ControlScreen and every listing screen are instances of the same <code>CC Shell</code> component, so <code>ControlScreen.css</code> is linked and its <code>.cc-control__*</code> classes are reused — the same approach SeatingPlanner takes.</p><p><code>.cc-control__page</code> already supplies the <code>cs-page</code> container context and <code>isolation: isolate</code>, so an open FilterBar dropdown paints above the table for free.</p><h2 id="the-header-is-a-contextual-override" tabindex="-1">The header is a contextual override <a class="header-anchor" href="#the-header-is-a-contextual-override" aria-label="Permalink to &quot;The header is a contextual override&quot;">​</a></h2><p><code>get_design_context</code> on the Chrome instance returns the CC Shell component&#39;s <strong>default</strong> header — avatar, user details, Logout / View Site. The rendered frame shows <strong>none of it</strong>: just the title &quot;Orders&quot;. The screenshot is authoritative. Built as a title-only <code>.cc-header--control</code>, which needed no new CSS, only fewer children.</p><p>This is worth remembering for the other ~400 screens: the listing header is always a bare title.</p><h2 id="token-gaps-and-figma-side-slips" tabindex="-1">Token gaps and Figma-side slips <a class="header-anchor" href="#token-gaps-and-figma-side-slips" aria-label="Permalink to &quot;Token gaps and Figma-side slips&quot;">​</a></h2><p>All three were raised as STOPs and resolved by the designer on 2026-09-17.</p><table tabindex="0"><thead><tr><th>#</th><th>Finding</th><th>Where</th><th>Resolution</th></tr></thead><tbody><tr><td>1</td><td><code>--spacing-5</code> <strong>primitive</strong> (not <code>--ai-spacing-5</code>) bound to the ORDER NO header + body cells</td><td><code>3648:164918</code>, every ORDER NO cell</td><td>Normalise to <code>--ai-spacing-5</code>. <strong>Figma still needs fixing.</strong></td></tr><tr><td>2</td><td>Raw <code>px-[12px] py-[8px] gap-[8px]</code> — unbound — on the ACCOUNT CODE / QTY / ORDER TOTAL header cells, where the other three headers bind <code>--ai-spacing-5</code> / <code>--ai-spacing-2</code></td><td><code>3648:164936/164942/164948</code></td><td>Normalise all six to <code>--ai-spacing-5</code> / <code>--ai-spacing-2</code>. This also removed a real 4px header/body misalignment visible in the design. <strong>Figma still needs fixing.</strong></td></tr><tr><td>3</td><td>Mobile customer role bound to raw <code>12px</code></td><td><code>3648:164504</code></td><td>Normalise to <code>--ai-font-fixed-xxs</code>. <strong>Figma still needs fixing.</strong></td></tr></tbody></table><p>Mobile header tracking is a raw <code>0.6px</code>; that is <code>--ai-tracking-7</code> (0.05em) at the 11px font size, so the token is used. Letter-spacing is in any case a documented raw-px exception.</p><h2 id="contextual-overrides-case-b" tabindex="-1">Contextual overrides (Case B) <a class="header-anchor" href="#contextual-overrides-case-b" aria-label="Permalink to &quot;Contextual overrides (Case B)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Base component</th><th>Override</th><th>Why not a variant</th></tr></thead><tbody><tr><td>Account chip</td><td><code>btn btn--tertiary btn--sm</code></td><td><code>border-color: var(--ai-border-secondary)</code></td><td>Tertiary&#39;s own border token is transparent in every mode. Designer&#39;s call: scope it, don&#39;t add a Button variant.</td></tr><tr><td>Initials avatar</td><td><code>avatar avatar--initials</code></td><td>brand palette (<code>--ai-surface-brand-soft-extra</code> / <code>--ai-text-brand</code>)</td><td>The Avatar component&#39;s own <code>--initials</code> is the <strong>info</strong> palette. Applied by analogy with the chip; flagged for the designer to formalise if it turns out to be house style.</td></tr></tbody></table><h2 id="column-widths-are-intrinsic-not-the-figma-pixels" tabindex="-1">Column widths are intrinsic, not the Figma pixels <a class="header-anchor" href="#column-widths-are-intrinsic-not-the-figma-pixels" aria-label="Permalink to &quot;Column widths are intrinsic, not the Figma pixels&quot;">​</a></h2><p>Figma fixes ORDER NO 114, QTY 100, kebab 48, checkbox 32, and min-widths of 250 (CUSTOMER) / 170 (ACCOUNT). None maps to an <code>--ai-*</code> token, so writing them would breach the hardcoded-dimension rule. <code>.datatables__col--hug</code> shrink-wraps the narrow columns and the wide ones absorb the remainder — same visual result, and it holds at every width, which matters because the content column resizes with no window resize (CLAUDE.md §4a).</p><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><p>Container queries only — no <code>matchMedia</code>, no viewport media query. Mobile keeps <strong>ORDER + CUSTOMER</strong>; the other four columns move into the kebab detail row, which the renderer builds from the same column list that produced the header, so the two cannot drift.</p><p>Measured at 390px viewport (in-shell, not the component&#39;s own 384px canvas): content column 338px → datatable 275px → table 273px, <code>scrollWidth === clientWidth</code>, no overflow.</p><p>Two fixes were needed to get there, both found by measuring rather than eyeballing:</p><ol><li>The row-edit button was built as <code>btn--icon</code> (40px). Figma&#39;s node is <code>2926:3566</code> — the Secondary <code>Icon Only=True, Size=xs</code> variant, i.e. the stock <strong><code>btn--icon btn--xs</code></strong> (24×24). The wrong size cost 28px and pushed the kebab column off-screen.</li><li>The mobile kebab cell needed <code>padding-inline: var(--ai-spacing-0)</code> per Figma. The first attempt silently lost the cascade: <code>.datatables--orders td.&lt;class&gt;</code> is (0,2,1) against the blanket cell rule&#39;s (0,2,2) — equal class count, more elements, so the blanket rule won. <code>.table</code> was added to the selector to lift it to (0,3,1).</li></ol><p>Figma also shortens the ORDER NO header to &quot;Order&quot; on mobile. CSS cannot swap text and JS must not read a container query, so both strings are rendered and the container query picks one (<code>.datatables__label--full</code> / <code>--short</code>).</p><h2 id="demo-chrome-no-theme-cog-on-this-screen" tabindex="-1">Demo chrome: no theme cog on this screen <a class="header-anchor" href="#demo-chrome-no-theme-cog-on-this-screen" aria-label="Permalink to &quot;Demo chrome: no theme cog on this screen&quot;">​</a></h2><p>This template loads <strong><code>src/styles/theme-param.js</code></strong>, not <code>src/components/dark-mode-toggle.js</code> — the only CC screen that does.</p><p>Both apply the saved theme from <code>&lt;head&gt;</code> before first paint, using the same <code>demo-theme</code> localStorage key, so the light/dark choice still follows a visitor here from any other page. The difference is that <code>dark-mode-toggle.js</code> also injects the <strong>demo toolbar</strong> — the fixed gear tab pinned to the right edge. Dropped at the designer&#39;s request (2026-09-17): this template is the shell for ~400 real Control Centre screens, and a demo affordance floating over it reads as part of the product rather than as demo furniture.</p><p>The in-product control is unaffected — the <strong>User Menu dropdown still carries its ThemeToggle</strong> (Figma HeaderGroup <code>4146:6685</code>), driven by <code>ThemeToggle.js</code>. That is the real light/dark switch for this surface; only the demo tab is gone.</p><p>Other CC screens keep their cog; nothing shared was changed.</p><h2 id="page-padding-and-the-scrollbar-gutter" tabindex="-1">Page padding and the scrollbar gutter <a class="header-anchor" href="#page-padding-and-the-scrollbar-gutter" aria-label="Permalink to &quot;Page padding and the scrollbar gutter&quot;">​</a></h2><p><code>.cc-control__page</code> scrolls and sets <code>scrollbar-gutter: stable</code>, which reserves a 15px gutter on the <strong>end edge only</strong>. ControlScreen compensates by trimming <code>padding-right</code> at both breakpoints, so the content sits evenly against it.</p><table tabindex="0"><thead><tr><th>Breakpoint</th><th>padding L</th><th>padding R</th><th>+ gutter</th><th>visual L / R</th></tr></thead><tbody><tr><td>Desktop (≥768)</td><td><code>--ai-spacing-6</code> (24)</td><td><code>--ai-spacing-4</code> (12)</td><td>15</td><td>24 / 27</td></tr><tr><td>Mobile (≤767)</td><td><code>--ai-spacing-4</code> (12)</td><td><code>--ai-spacing-0</code> (0)</td><td>15</td><td>12 / 15</td></tr></tbody></table><p>The mobile row was <code>--ai-spacing-2</code> (6px) until 2026-09-17, which read as <strong>12 / 21</strong> — a 9px lean, three times the desktop tolerance, and present on every CC screen rather than just this one. Fixed in <code>ControlScreen.css</code> so all of them benefit.</p><p><strong>Exactly even is not reachable by trimming at mobile</strong>: the reserved gutter (15px) is already wider than the 12px left padding, so the only symmetric option is <code>scrollbar-gutter: stable both-edges</code>, which costs 15px of content on each side of a 390px screen. Deliberately not taken.</p><p><strong>Do not re-declare <code>padding</code> on <code>.cc-control__page--listing</code>.</strong> It has the same specificity as <code>.cc-control__page</code> but loads later, so a shorthand there wins and silently restores the untrimmed right padding — which is exactly how the 39px right gap arose on 2026-09-17.</p><h2 id="filter-pickers-—-which-dropdown-each-chip-opens-2026-09-17" tabindex="-1">Filter pickers — which dropdown each chip opens (2026-09-17) <a class="header-anchor" href="#filter-pickers-—-which-dropdown-each-chip-opens-2026-09-17" aria-label="Permalink to &quot;Filter pickers — which dropdown each chip opens (2026-09-17)&quot;">​</a></h2><p>Figma <code>3681:99951</code> (&quot;Filter Dropdown / Options&quot;) shows a chip&#39;s picker anchored under it. The assignment per filter is the designer&#39;s (2026-09-17), and every Type is <strong>already built</strong> in <code>src/patterns/FilterDropdowns/</code> — nothing new was drawn or written for this screen.</p><table tabindex="0"><thead><tr><th>Filter</th><th>Asked for</th><th>FilterDropdowns Type</th><th>Node</th><th><code>type</code> in config</th></tr></thead><tbody><tr><td>Customer</td><td>selection options w/subset</td><td>Select Options w/subtext</td><td><code>3039:5628</code></td><td><code>select-options</code></td></tr><tr><td>User Code</td><td>predictive text</td><td>Predictive Text Options</td><td><code>3039:5625</code></td><td><code>predictive</code></td></tr><tr><td>Account</td><td>multi select</td><td>Multi Select</td><td><code>3039:5629</code></td><td><code>multi-select</code></td></tr><tr><td>Account Code</td><td>predictive text</td><td>Predictive Text Options</td><td><code>3039:5625</code></td><td><code>predictive</code></td></tr><tr><td>Order No.</td><td>text</td><td>Text</td><td><code>3039:5633</code></td><td><code>text</code></td></tr><tr><td>Add Filters</td><td>more filters</td><td>More Filters</td><td><code>3039:5637</code></td><td><code>more-filters</code></td></tr></tbody></table><p>Two notes on the mapping:</p><ul><li><strong>&quot;w/subset&quot; → w/subtext.</strong> Figma has no &quot;subset&quot; type; <code>Select Options w/subtext</code> is the one that renders a name plus a secondary line, which is what the Customer rows need (name + account · code). Read as a typo.</li><li><strong>Plain <code>Predictive Text</code> (<code>3039:5638</code>) does not exist in code.</strong> The pattern consolidated it into <code>Predictive Text Options</code> on the grounds that predictive always reveals options — so both predictive filters get that Type.</li></ul><p><strong>It is config, not markup.</strong> Each filter in <code>listing-data.js</code> names its <code>type</code>; <code>ListingScreen.js</code> <code>FILTER_PANELS</code> maps that to the pattern&#39;s markup. Assigning a different picker to a filter is a one-word change, which is what makes this survivable across ~400 screens.</p><h3 id="initialisation-order" tabindex="-1">Initialisation order <a class="header-anchor" href="#initialisation-order" aria-label="Permalink to &quot;Initialisation order&quot;">​</a></h3><p>The chips are rendered by <code>ListingScreen.js</code> on <code>DOMContentLoaded</code>, which is <strong>after</strong> <code>FilterItem.js</code> and <code>FilterDropdowns.js</code> have already auto-initialised whatever was in the static markup. The rendered nodes would therefore be inert. <code>ListingScreen.js</code> dispatches <code>listing:rendered</code> and a module listener re-initialises — <strong>scoped to the new nodes</strong>, because <code>FilterItem.init</code> has no idempotency guard and re-running it over the document would bind every existing chip twice. (<code>FilterDropdowns</code> does guard, via <code>__filterDropdowns</code>.)</p><p><code>Type=More Filters</code> carries no <code>data-filter-dropdowns</code> attribute and is not initialised — correct, not a miss: it is chips only, with no select, predictive, search or apply behaviour. The pattern&#39;s own demo has it the same way.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>ListingScreen.html</code></td><td>Full screen. Shell copied from ControlScreen (same Figma component); page content is the listing.</td></tr><tr><td><code>ListingScreen.css</code></td><td>Only the content column. 63 lines — everything else is reused.</td></tr><tr><td><code>ListingScreen.js</code></td><td>Config-driven renderer: thead, tbody, detail rows, pagination.</td></tr><tr><td><code>listing-data.js</code></td><td>Column config + default filters + rows + paging. <strong>The swap point for real data.</strong></td></tr><tr><td><code>Datatables.css</code></td><td><code>.datatables--orders</code> lives with its component, since Type=Orders is a Datatables variant.</td></tr></tbody></table><h2 id="backend-handover" tabindex="-1">Backend handover <a class="header-anchor" href="#backend-handover" aria-label="Permalink to &quot;Backend handover&quot;">​</a></h2><p>Markers: <code>listing-default-filters</code>, <code>listing-export</code>, <code>listing-orders-rows</code>. Contract sketch in <code>listing-data.js</code>; rows are shaped from the live <code>/control/orders</code> screen so the mapping is one-to-one. See HANDOVER.md.</p><h2 id="still-open" tabindex="-1">Still open <a class="header-anchor" href="#still-open" aria-label="Permalink to &quot;Still open&quot;">​</a></h2><ul><li><strong>Pass 2</strong>: filter dropdowns, apply/clear, sort, paging, the view menus, row expand.</li><li><strong>Figma fixes</strong>: the three binding slips above.</li><li><strong>Mobile frame <code>3648:161126</code> is titled &quot;Articles&quot;</strong>, not &quot;Orders&quot; — stale title on the designer&#39;s side. Built as &quot;Orders&quot; to match the desktop frame and the live screen.</li><li><strong>Pagination active state</strong>: Figma paints it <code>--ai-datatable-table-footer-bg</code>, which in CC <strong>light</strong> resolves to the same white as the pagination container — so weight alone carries the state. <code>aria-current=&quot;page&quot;</code> is set, but this is a contrast question for the designer, not something to &quot;fix&quot; in code.</li></ul><h2 id="filter-selection-add-filters-pass-2b" tabindex="-1">Filter selection + Add Filters (pass 2b) <a class="header-anchor" href="#filter-selection-add-filters-pass-2b" aria-label="Permalink to &quot;Filter selection + Add Filters (pass 2b)&quot;">​</a></h2><ul><li><strong>Account starts fully deselected.</strong> Its chip therefore renders Default, and ticking 1–3 boxes lists them, 4+ rolls up to <code>&lt;first&gt;, and N more</code> — the rollup is FilterItem&#39;s, not this screen&#39;s (see FilterBar notes).</li><li><strong>Add Filters moves a facet onto the bar.</strong> <code>LISTING_ORDERS_MORE_FILTERS</code> is now a list of full filter configs rather than bare names, because a chosen facet needs the same <code>type</code>/<code>options</code> as a default filter to open a working dropdown. <code>init()</code> works on a shallow copy of both filter arrays so <code>LISTING_SCREENS</code> still describes a <em>fresh</em> screen afterwards.</li><li><strong><code>FilterDropdownItem.js</code> must be loaded.</strong> It carries the option rows&#39; click handler; FilterDropdowns.js does not. Without it the pickers open and nothing can be selected, silently.</li></ul><h3 id="open-with-the-designer" tabindex="-1">Open with the designer <a class="header-anchor" href="#open-with-the-designer" aria-label="Permalink to &quot;Open with the designer&quot;">​</a></h3><p>The five default filters have assigned dropdown types (Customer = Selection Options, User Code / Account Code = Predictive, Account = Multi Select, Order No. = Text). The nine More Filters facets have <strong>not</strong> been assigned one, so each carries <code>type: &#39;text&#39;</code> — the only type needing no invented option list. Three clearly want a date picker, which FilterDropdowns already provides (Date Range / Date In the last / Date Equal To) but this screen does not yet build; the status/method/type facets want Multi Select once their real option lists are known. Each is a one-word change in <code>listing-data.js</code>.</p><h2 id="table-filtering-pass-2c" tabindex="-1">Table filtering (pass 2c) <a class="header-anchor" href="#table-filtering-pass-2c" aria-label="Permalink to &quot;Table filtering (pass 2c)&quot;">​</a></h2><p>Front-end filtering over the mock rows, so the screen is demonstrable before a backend exists. <code>TODO(backend:Listing)</code> in <code>listing-data.js</code> marks the seam: the real <code>/control/orders</code> filters server-side and returns the counts with the rows, at which point <code>field</code> becomes the query-parameter name and <code>applyFilters()</code> goes away.</p><p><strong>Config, not code.</strong> Each filter carries a <code>field</code> naming the row property it tests (<code>customer.name</code> walks into the object), so nothing in the renderer knows an Orders column from a Contacts one.</p><table tabindex="0"><thead><tr><th>Filter</th><th>Type</th><th>Field</th><th>Match</th></tr></thead><tbody><tr><td>Customer</td><td>Selection Options</td><td><code>customer.name</code></td><td>exact, any of</td></tr><tr><td>User Code</td><td>Text</td><td><code>userCode</code></td><td>contains</td></tr><tr><td>Account</td><td>Multi Select</td><td><code>account</code></td><td>exact, any of</td></tr><tr><td>Account Code</td><td>Text</td><td><code>accountCode</code></td><td>contains</td></tr><tr><td>Order No.</td><td>Text</td><td><code>orderNo</code></td><td>contains</td></tr></tbody></table><p>A <strong>Text</strong> filter is a search — one typed fragment, matched loosely. Every other type is a pick-list whose values came from the row data itself, so they match exactly, and several picks mean &quot;any of these&quot;. Filters combine with AND.</p><p><code>User Code</code> and <code>Account Code</code> were Predictive; the designer moved both to plain Text on 2026-09-17. <code>userCode</code> has no column — it exists only so that filter has something to test.</p><p><strong>Values arrive by event, not by reading the chip.</strong> <code>FilterItem</code>&#39;s label rolls 4+ values up into <code>&lt;first&gt;, and 3 more</code>, which is lossy, so the bar announces <code>filter-bar:change</code> (<code>{ name, values }</code>) on every commit and clear.</p><p><strong>A field-less filter is not active.</strong> It cannot narrow the table, so it must also not make the footer report a count it did not produce — the nine More Filters facets are all in that position until they get types and fields.</p><h3 id="empty-state-—-flagged" tabindex="-1">Empty state — flagged <a class="header-anchor" href="#empty-state-—-flagged" aria-label="Permalink to &quot;Empty state — flagged&quot;">​</a></h3><p><code>TODO(design:Listing)</code>: <strong>Datatables has no empty state in Figma.</strong><code>.cc-listing__empty</code> mirrors EventPicker&#39;s <code>Type=Event Picker (no results)</code> (3108:6659) token for token, that being the established treatment on the CC surface, rather than inventing a second one. It wants a Datatables variant of its own.</p><p>Note the cell keeps table display and the flex column is a <code>div</code> inside it: a <code>&lt;td&gt;</code> set to <code>display: flex</code> leaves table layout and then ignores its own <code>colspan</code>, collapsing the empty state into the first column.</p><h2 id="saved-views-pass-2d" tabindex="-1">Saved views (pass 2d) <a class="header-anchor" href="#saved-views-pass-2d" aria-label="Permalink to &quot;Saved views (pass 2d)&quot;">​</a></h2><p>A view IS a filter set: which filters are on the bar, in what order, holding what values. FilterBar owns the list and its rows; the screen owns what a row MEANS, so snapshots live here in a <code>WeakMap</code> keyed by the row element.</p><ul><li><strong>Save view</strong> → names the view → the snapshot is taken and the row selected.</li><li><strong>Selecting</strong> a view restores its snapshot: the filter list, the More Filters remainder, and every value. Chips are rebuilt (this is the one case where a full chip re-render is right) with their pickers already showing the restored state — ticked checkboxes, filled fields, selected option rows — which is why the panel builders take the values.</li><li>A row with <strong>no snapshot</strong> — the shipped mock views, or a brand-new empty one — stands for the unfiltered listing.</li><li>After restoring, <code>bar.resetSaveView(values)</code> re-baselines, so the Save view CTA is not owed. Change something and it returns; undo the change and it goes again.</li></ul><p>The bar establishes its baseline before these chips exist, so the screen also calls <code>resetSaveView</code> after the FIRST render — otherwise the bar reads the initial chips as a change and offers to save the view it just opened on.</p><p>TODO(backend:Listing): in memory, like the rest of the saved-views mocking. → <code>POST /control/orders/views { name, filters:[{name,values}] }</code> and <code>GET /control/orders/views</code>.</p><p>Also fixed here: FilterBar&#39;s empty-view rule hid <code>.filter-bar__chips &gt; .filter-item</code>, but a chip with a picker is WRAPPED in <code>.filter-bar__chip</code>, so the listing&#39;s chips stayed visible in an empty view. The wrapper now carries <code>.filter-bar__chip--add</code> so the rule can spare the Add Filters chip.</p><h2 id="search-pass-2e" tabindex="-1">Search (pass 2e) <a class="header-anchor" href="#search-pass-2e" aria-label="Permalink to &quot;Search (pass 2e)&quot;">​</a></h2><p>Free text narrows the table alongside the chips — a search inside a filtered view searches that view, not the whole listing. The threshold lives in FilterBar; the screen just reacts to <code>filter-bar:search</code>.</p><p><strong>What it looks at is derived from the COLUMN config, not the row object.</strong> Scanning the row would match things the table never shows: every row would be a hit for &quot;photos&quot;, because that is in the avatar URL. So <code>searchableText()</code> walks the columns and reads <code>text</code> / <code>chip</code> values plus a <code>user</code> cell&#39;s name and role.</p><p>By the same rule the hidden <code>userCode</code> is <strong>not</strong> searchable — it is not on screen, and it has its own filter chip. Worth a check with the designer if the expectation is that search reaches fields the listing does not display.</p><p><strong>Search is not part of a saved view</strong>, and survives switching between them: a view is a filter set, and the search is a transient look inside whichever view is open. It therefore does not make the Save view CTA appear either.</p><h2 id="real-orders-schema-pass-3" tabindex="-1">Real Orders schema (pass 3) <a class="header-anchor" href="#real-orders-schema-pass-3" aria-label="Permalink to &quot;Real Orders schema (pass 3)&quot;">​</a></h2><p>Columns and filters are now the live screen&#39;s, read from the Affino source (client_key Comrz). Provenance is recorded at the top of <code>listing-data.js</code>. Mark, 2026-09-18: replicate the DATA; the presentation and interaction move to the new design system — &quot;that is the task&quot;.</p><h3 id="what-is-a-reproduction" tabindex="-1">What is a reproduction <a class="header-anchor" href="#what-is-a-reproduction" aria-label="Permalink to &quot;What is a reproduction&quot;">​</a></h3><ul><li><strong>20 data columns</strong> from <code>OrderProcessingDef.cfm</code> (<code>CProperties</code>, rows flagged <code>l</code>), plus Account / Account Code which are present on the standalone screen and suppressed only when embedded on an account record.</li><li><strong>Seven sortable columns</strong>, the explicit <code>hs</code> whitelist from <code>OrderProcessings.cfm</code>: <code>OrderNo.</code> <code>Date</code> <code>Customer</code> <code>Account</code> <code>Value</code><code>Status</code> <code>PaymentStatus</code>. Everything else silently falls through, so Qty, Order Total and Tax carry no sort control however sortable they look. Default <code>Date</code> descending.</li><li><strong>Six default filters</strong> — the live &quot;Simple Search&quot; form. Customer and Order Owner are autocompletes (→ Predictive); User Code, Account, Account Code and Order No. are plain text. Customer and User Code are DIFFERENT fields shown at once, as are Account and Account Code.</li><li><strong>47 advanced filters</strong> with their real widget types and, where the source defines them statically, their real option lists (Order Status ×16, Payment Status ×3, Order Type ×2, Sub Order Type ×7, Order Method ×2 …). DB-lookup option VALUES are mock; the names and types are not.</li><li><code>TaxRule</code> is deliberately absent — accepted by the controller and used in the query, but no form renders a control for it. Building one would be inventing UI.</li></ul><h3 id="what-is-new-and-says-so" tabindex="-1">What is new, and says so <a class="header-anchor" href="#what-is-new-and-says-so" aria-label="Permalink to &quot;What is new, and says so&quot;">​</a></h3><ul><li><strong>The chip bar.</strong> The live screen swaps a Simple form for an Advanced one behind a <code>+</code>; it has no default-chips / Add-Filters model.</li><li><strong>The search field.</strong> The live <code>Search</code> param is an <code>&lt;input type=&quot;submit&quot;&gt;</code> — the code only tests <code>Len(Trim(url.Search))</code> to mean &quot;a search was submitted&quot;. There is no keyword box on that screen at all.</li><li><strong>Edit Columns.</strong> No column picker and no per-user column preference exist today. Built as a working prototype at Mark&#39;s direction.</li></ul><h3 id="progressive-columns" tabindex="-1">Progressive columns <a class="header-anchor" href="#progressive-columns" aria-label="Permalink to &quot;Progressive columns&quot;">​</a></h3><p>Every column carries a <code>tier</code>; tiers reveal as the TABLE widens (~180px steps, <code>@container</code> on the datatable&#39;s own inline size). Tier 1 is the row&#39;s identity and is always present. Measured: 5 columns at a 420px page, 22 at 2300px. At a 900px page the table is NARROWER than at 700px because the CC sidebar expands — a viewport query would show more columns in less space, which is the §4a failure mode exactly.</p><p>Edit Columns answers a different question from the tier: the tier decides whether there is ROOM, the picker whether a column is WANTED. A wanted column with no room still hides, and the panel says &quot;No room at this width&quot; rather than showing a tick against something invisible. That state is read back off the DOM (hidden <code>th</code> without <code>--off</code>) rather than by re-deriving the breakpoints in JS, which would drift from the stylesheet. The notes refresh from a <code>ResizeObserver</code> on the table, never <code>matchMedia</code>.</p><p>Order No. and Customer are locked in the picker — without them the table is a list of anonymous rows.</p><p>TODO(backend:Listing): column choices are in memory, like the saved views.</p><h2 id="sort-paging-and-column-widths-pass-4" tabindex="-1">Sort, paging and column widths (pass 4) <a class="header-anchor" href="#sort-paging-and-column-widths-pass-4" aria-label="Permalink to &quot;Sort, paging and column widths (pass 4)&quot;">​</a></h2><p>Display follows best practice, not the live screen — Mark, 2026-09-18: &quot;we dont need to follow what the old one does in terms of display. its just about the data.&quot; So the live <code>SELECT TOP 500</code> cap is deliberately NOT reproduced; paging here covers the whole result set.</p><p><strong>Order of operations: filter → sort → page.</strong> Paging first would sort only the visible slice; sorting first would page a list the filter is about to change. Any of the three resetting to page 1 where the old page number stops meaning anything (a new filter, a new search, a re-sort) — except rows-per-page, which recomputes the page so the first visible row stays on screen: 20 → 50 while reading page 4 should widen the view around where you were.</p><p><strong>Sorting</strong> is by VALUE, not rendered text — &quot;£1,000.00&quot; sorts before &quot;£9.95&quot; as a string. A value counts as numeric only if the whole of it is one, so &quot;£9.95&quot; and &quot;100412&quot; are numbers while &quot;EXT-0412&quot; and &quot;Paid Full&quot; are not. A second click on the same column reverses; a first click on a new one starts descending, which is what a date or a value is usually wanted by.</p><p><strong>Pagination is windowed</strong> — first, last, current ± 1, gaps elided, constant width so the control does not resize as you page: <code>1 2 3 4 … 14</code>, <code>1 … 6 7 8 … 14</code>, <code>1 … 11 12 13 14</code>.</p><p><strong>140 mock rows</strong>, generated deterministically from the ten seed rows, so paging and sorting are demonstrable and a screenshot stays reproducible.</p><h3 id="the-customer-column-squeeze-—-what-it-actually-was" tabindex="-1">The Customer column squeeze — what it actually was <a class="header-anchor" href="#the-customer-column-squeeze-—-what-it-actually-was" aria-label="Permalink to &quot;The Customer column squeeze — what it actually was&quot;">​</a></h3><p>Not a share-of-slack problem. <code>Table.css</code> sets <code>white-space: nowrap</code> on every <code>th</code> and <code>td</code> so a wide table scrolls rather than squashes. Right for a code or a date; wrong for &quot;Awaiting Payment Confirmation&quot;, which on its own made the table 1281px inside a 1055px container. Once the table overflows there is no slack at all, and every fluid column collapses to min-content — Customer rendering as &quot;Mari…&quot; was that, not a width share.</p><p>Three changes, in the order they mattered:</p><ol><li><strong><code>--snug</code></strong>: shrink-to-fit that unsets the nowrap, for the enumerated columns. Setting <code>width: 1%</code> alone did nothing, because the nowrap it was meant to escape comes from the Table component, not from Datatables.css. Payment Status 240px → 118px, Order Status 173 → 105.</li><li><strong>Customer is the only fluid column</strong> — everything else hugs or snugs, so it absorbs all the slack rather than an eighth of it.</li><li><strong>Tier thresholds re-tuned against measured widths</strong> rather than an even 180px step. Revealing a tier ~100px too early does not overflow the table, it silently starves Customer — which reads as a truncation bug rather than as a breakpoint being wrong, and is why these are measured.</li></ol><p>Measured after: no overflow at any width from 420px to 2600px, Customer between 169px and 569px, 5 columns up to 16.</p><p><strong>Known limitation:</strong> the tier is width-only, so switching columns OFF in Edit Columns does not promote the remaining ones into the freed space. Someone who wants Pro Forma ID on a 1500px screen cannot get it by turning others off. Making the reveal respond to how many columns are ON would fix it, and is a bigger change than it looks — worth doing deliberately rather than now.</p><h2 id="edit-columns-reordering-and-the-gap-pass-5" tabindex="-1">Edit Columns: reordering, and the gap (pass 5) <a class="header-anchor" href="#edit-columns-reordering-and-the-gap-pass-5" aria-label="Permalink to &quot;Edit Columns: reordering, and the gap (pass 5)&quot;">​</a></h2><h3 id="drag-to-reorder" tabindex="-1">Drag to reorder <a class="header-anchor" href="#drag-to-reorder" aria-label="Permalink to &quot;Drag to reorder&quot;">​</a></h3><p>Each row in the panel has a grip. The row is made <code>draggable</code> only while the pointer is on that grip, so the checkbox stays clickable and a stray drag on the label does not start a reorder.</p><p>Only the LABELLED columns move — the checkbox, spacer, edit and kebab columns are structure. The reorder happens on the labelled subset and is written back into the slots those columns occupied, so structure stays put.</p><p><strong>Reordering also re-tiers.</strong> A column&#39;s position IS its priority, so dragging one to the front is how you say &quot;show me this first&quot;. Without it, dragging a tier-9 column to the top would leave it hidden until 2600px, which reads as broken. Tiers are reassigned in pairs (<code>floor(i / 2) + 1</code>) to match the thresholds in Datatables.css, and the first two columns — whatever they now are — become the locked pair and are un-hidden if they had been switched off. This also answers the limitation flagged in pass 4: a column you want on a narrow screen is now reachable by dragging it up, rather than unreachable.</p><h3 id="the-gap-after-hiding-a-column" tabindex="-1">The gap after hiding a column <a class="header-anchor" href="#the-gap-after-hiding-a-column" aria-label="Permalink to &quot;The gap after hiding a column&quot;">​</a></h3><p>Customer was the only column that could grow, so ALL the freed width pooled in it: hiding one column stretched Customer from 267px to 372px, leaving a visible gap between the name and the next column.</p><p><code>max-inline-size</code> does <strong>not</strong> fix this — a max-width on a table cell is advisory under <code>table-layout: auto</code>, and the column stayed at 372. Two changes did:</p><ol><li>Customer gets a <strong>preferred</strong> width (<code>width: var(--ai-size-6)</code>), not <code>auto</code>. Auto layout treats <code>width</code> as a preference, so it still shrinks when space is tight but stops growing at 320px.</li><li>A <strong>spacer column</strong> before the actions absorbs whatever is left. Nothing real stretches, the columns stay closed up, and the row rules still run the full width of the table.</li></ol><p>The spacer is <code>role=&quot;presentation&quot;</code> with no accessible name, so screen readers do not announce an empty column.</p><h2 id="columns-are-part-of-the-view-pass-6" tabindex="-1">Columns are part of the view (pass 6) <a class="header-anchor" href="#columns-are-part-of-the-view-pass-6" aria-label="Permalink to &quot;Columns are part of the view (pass 6)&quot;">​</a></h2><p>Mark, 2026-09-18: editing the table &quot;constitutes a possible new view (workflow)&quot; — so a column change is a view change and must surface the same Save view CTA as a filter change.</p><p>The bar owns the CTA but must not learn what a column is, so it exposes <code>setViewExtra(string)</code>: an opaque value folded into the signature it already compares. The screen sends <code>columnState()</code> — the column key order plus the hidden set — on every visibility toggle and every reorder, and before re-baselining on a view switch.</p><p>Snapshots carry <code>columns</code> and <code>hiddenColumns</code> alongside the filters, COPIED rather than referenced: reordering rewrites each column&#39;s tier in place, so a stored reference would quietly follow the live table instead of preserving the layout as saved.</p><p>Verified round trip: hide a column → CTA appears; restore it → CTA goes (the signature is back at baseline, not merely &quot;something happened&quot;); reorder → CTA appears; save → CTA goes and the layout sticks; switch to All Orders → the original column order returns; switch back → the saved layout returns, CTA still hidden.</p><h2 id="cell-truncation-and-rhythm-pass-7" tabindex="-1">Cell truncation and rhythm (pass 7) <a class="header-anchor" href="#cell-truncation-and-rhythm-pass-7" aria-label="Permalink to &quot;Cell truncation and rhythm (pass 7)&quot;">​</a></h2><p>Designer, 2026-09-18: Customer too wide, long enumerated values should truncate, tighter line heights.</p><ul><li><strong>Customer&#39;s preferred width 320px → 240px.</strong></li><li><strong>Enumerated values truncate</strong> rather than wrap. The cap lives on an INNER span, not on the cell: <code>max-inline-size</code> on a <code>td</code> is advisory under <code>table-layout: auto</code>, so the column still sizes to max-content and nothing truncates. A block inside the cell has a max-content of its own, which is what actually caps the column. The full value stays in the <code>title</code>, and the kebab detail row deliberately does NOT truncate — it exists to show values in full.</li><li><strong>Line heights</strong>: <code>th</code> → <code>--ai-leading-xs</code> (16px), <code>td</code> → <code>--ai-leading-sm</code> (20px). Scoped to <code>.datatables--orders</code> rather than changed in <code>Table.css</code>, since the Seating Planner&#39;s tables use that component and were not part of this ask.</li></ul><h3 id="tier-thresholds-re-measured-again" tabindex="-1">Tier thresholds, re-measured (again) <a class="header-anchor" href="#tier-thresholds-re-measured-again" aria-label="Permalink to &quot;Tier thresholds, re-measured (again)&quot;">​</a></h3><p>Switching the enumerated columns from wrapping to truncating made them <strong>wider</strong>, not narrower — a 160px cap plus padding beats a two-line wrap — so the previous thresholds overflowed the table at every width past tier 4. That does not present as overflow so much as Customer silently collapsing back to 127px, which is the same symptom as the original bug and a good reason to measure rather than nudge.</p><p>Thresholds are now the measured cumulative width of every column up to that tier, relaxed by ~55px. That 55 is the dial between &quot;more columns&quot; and &quot;roomier Customer&quot; — the only number in the set that is a judgement rather than a measurement. At a 1500px page it is the difference between 9 columns with Customer at 199px and 7 columns with Customer at 240px.</p><p>Measured after: no overflow from 420px to 3800px; 6 columns at 420px, 23 at 3800px; Customer at its 240px preference everywhere except where space is genuinely tight.</p><h2 id="adaptive-column-fill-pass-8-—-replaces-the-tier-system" tabindex="-1">Adaptive column fill (pass 8) — replaces the tier system <a class="header-anchor" href="#adaptive-column-fill-pass-8-—-replaces-the-tier-system" aria-label="Permalink to &quot;Adaptive column fill (pass 8) — replaces the tier system&quot;">​</a></h2><p>Designer, 2026-09-18: dead space where another column would have fitted, and &quot;I really want to make this a strong feature of the new listing screens.&quot;</p><p>The tier steps could never deliver it. CSS can only reveal a column at a width chosen in advance, so between two steps the table always carried slack — ~400px on a 780px table, room for two more columns. Deciding what fits means knowing how wide each column WANTS to be, and only layout can answer that.</p><p>So the fit is measured:</p><ol><li><strong>Measure</strong> — show every column and put the TABLE at <code>width: max-content</code>, read each column&#39;s width, restore. One task, so nothing is painted.</li><li><strong>Fill</strong> — walk the columns in order, adding each while it still fits. Stop at the FIRST that does not rather than skipping to a narrower one further down: order is priority, and a table showing column 8 but not column 5 reads as a bug.</li><li><strong>Verify and correct</strong> — measure the result and drop the last column while the table is still over. A column&#39;s measured width is what it wants alone; beside different neighbours it can round a few pixels wider, which left one width 13px over. Checking the actual outcome beats padding the budget with a tolerance that would be wrong somewhere else.</li></ol><p>Driven by a <code>ResizeObserver</code> on the table body, never <code>matchMedia</code> — the CC sidebar changes this width with no window resize (CLAUDE.md §4a). This is the case §4a allows JS for; a container query genuinely cannot express it.</p><h3 id="two-traps-worth-recording" tabindex="-1">Two traps worth recording <a class="header-anchor" href="#two-traps-worth-recording" aria-label="Permalink to &quot;Two traps worth recording&quot;">​</a></h3><ul><li><strong>Measuring with every column shown gives MIN-content, not natural width.</strong> Twenty columns over-constrain a container-width table and each collapses: a column that renders at 125px measured 74px, so the fit let two more columns in than actually fit. The table has to go to <code>max-content</code> for the pass.</li><li><strong><code>width: 1%</code> on the enumerated columns had to go.</strong> Shrink-wrapping every column means any width the fit does not use must pool somewhere — in Customer, which ballooned, or in a spacer column, which read as a gap. They are now <code>auto</code> and share the leftover between them, so there is never a visible gap; their content is still capped by <code>__truncate</code>, so a long value cannot dictate the width. <strong>The spacer column is gone</strong>, and with it the trailing dead space.</li></ul><h3 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h3><p>Gap is 0 at every width from 420px to 3800px: 2 columns at the narrowest, 20 at the widest, and the table always exactly fills its container.</p><p>Both column controls feed it. Hiding Order Total promotes Account into the freed space; dragging Invoices Sent to the top brings it on screen immediately and pushes the last one off. <code>tier</code> is gone from the config — <strong>order is priority</strong>, which makes the drag handle the control for &quot;show me this first&quot;.</p><h2 id="edit-columns-one-heading-not-a-note-per-row" tabindex="-1">Edit Columns: one heading, not a note per row <a class="header-anchor" href="#edit-columns-one-heading-not-a-note-per-row" aria-label="Permalink to &quot;Edit Columns: one heading, not a note per row&quot;">​</a></h2><p>The panel used to put &quot;No room at this width&quot; on every affected row — up to sixteen repetitions of the same sentence. Because the fit fills in ORDER, everything without room is the tail of the list, so a single heading at the cut says it once: above the line is on screen, below it is not.</p><p>It is the same <code>dropdown__label</code> as the &quot;Columns&quot; heading above it (designer, 2026-09-18).</p><p>The heading is PLACED into the list rather than the list being regrouped, so the rows keep their order — which matters, because they are draggable and dragging across the heading has to mean what it looks like it means.</p><p>Note a column switched OFF stays above the line: the heading is about room, not about the tick. Hiding a fitting column promotes the next one above the line, since the freed width is immediately re-fit.</p><h2 id="five-default-chips-for-every-screen" tabindex="-1">Five default chips, for every screen <a class="header-anchor" href="#five-default-chips-for-every-screen" aria-label="Permalink to &quot;Five default chips, for every screen&quot;">​</a></h2><p><code>DEFAULT_CHIPS = 5</code> in ListingScreen.js. A screen&#39;s config may list more filters as defaults — Orders lists the six its Simple Search form shows — and the extras move to the FRONT of the More Filters panel rather than being dropped. Order Owner is the first thing offered there, and adding it puts it straight back on the bar.</p><p>The split happens once at init, not at render time, so everything downstream — adding a filter, saving a view, restoring one — works on the real arrays and never has to know about the limit. The limit lives in the template rather than in <code>listing-data.js</code> because it applies to all ~400 screens.</p><h2 id="removing-a-filter-you-added" tabindex="-1">Removing a filter you added <a class="header-anchor" href="#removing-a-filter-you-added" aria-label="Permalink to &quot;Removing a filter you added&quot;">​</a></h2><p>Adding used to be one-way. The chip&#39;s face has no room for a remove control: FilterItem&#39;s leading slot holds <code>+</code> while empty and <code>×</code> once values are set, so a filter that is on the bar but has no value has nowhere to put one, and a second <code>×</code> on the right would fight the chevron (designer, 2026-09-18 — &quot;feels clunky&quot;). So removal lives in More Filters, which needs no new affordance:</p><p><strong>More Filters toggles.</strong> The panel is a stable CATALOGUE: a facet no longer leaves it when added, it turns solid with a check. Clicking it again takes the filter off the bar. Add and remove are the same gesture in the same place.</p><p>A second route — a <code>Remove filter</code> action under Apply inside the chip&#39;s own picker — was built and then taken out (designer, 2026-09-18: &quot;just keep more filters toggle for now&quot;). One way in and out is enough while the pattern settles; worth revisiting if removing turns out to be common enough that opening Add Filters each time grates.</p><p>Removing drops that filter&#39;s values with it and re-filters the table — verified: Order Status narrowed 20 rows to 9, removing it restored 20.</p><h3 id="model-change" tabindex="-1">Model change <a class="header-anchor" href="#model-change" aria-label="Permalink to &quot;Model change&quot;">​</a></h3><p><code>moreFilters</code> is a fixed catalogue and <code>config.added</code> holds the names the user has put on the bar, in order. <code>defaultFilters</code> — what the bar renders and what filtering looks names up in — is DERIVED from <code>baseFilters + added</code>. Saved views snapshot <code>added</code> rather than the arrays, since the arrays no longer move.</p><h3 id="flagged-for-figma" tabindex="-1">Flagged for Figma <a class="header-anchor" href="#flagged-for-figma" aria-label="Permalink to &quot;Flagged for Figma&quot;">​</a></h3><ul><li><strong>FilterItem has no &quot;already added&quot; state.</strong> Its slot is <code>+</code> or <code>×</code>, and neither means &quot;on the bar, click to remove&quot;. Implemented as the solid Default treatment with a check; it wants a real variant.</li></ul><h2 id="edit-columns-no-text-selection" tabindex="-1">Edit Columns: no text selection <a class="header-anchor" href="#edit-columns-no-text-selection" aria-label="Permalink to &quot;Edit Columns: no text selection&quot;">​</a></h2><p><code>user-select: none</code> on the whole <code>dropdown__panel--columns</code>. The rows are draggable, and a drag that starts anywhere but the grip otherwise sweeps a text selection across the list — which reads as the drag having failed rather than as having missed the handle (designer, 2026-09-18).</p><p>Scoped to this panel rather than set globally: nothing in it is worth copying, whereas a table of orders obviously is. Checkbox clicks and grip drags are unaffected — both re-verified after the change.</p><h2 id="date-filters" tabindex="-1">Date filters <a class="header-anchor" href="#date-filters" aria-label="Permalink to &quot;Date filters&quot;">​</a></h2><p>Order Date / Payment Date / Delivery Date use the real DatePicker. The screen now loads <code>DatePicker.css</code> + <code>DatePicker.js</code> and initialises pickers on <code>listing:rendered</code> alongside the other late-rendered components — without that the panel drew two inert readonly fields.</p><p><strong>Two date formats meet in the comparison</strong> and both are parsed rather than one pretending to be the other: rows carry ISO (<code>2026-09-28</code>, what a backend returns) and DatePicker writes what it displays (<code>28 Sep 2026</code>).</p><p><strong>Either end may be blank</strong> — an open-ended range is still a range. <code>valuesIn</code> keeps both positions, empty included, because collapsing <code>[&#39;&#39;, &#39;5 Sep 2026&#39;]</code> to one value would be read as &quot;from&quot; rather than &quot;up to&quot;. FilterItem drops the empty half from the chip&#39;s label by itself.</p><p>The same code serves the numeric ranges (Order No. Range, Price Range), which use the identical two-field widget — <code>toNumber</code> strips currency symbols and separators so &quot;£1,204.95&quot; compares.</p><p>Measured: 20–28 Sep gives 18 rows, all within range; &quot;up to 5 Sep&quot; gives 94, the latest being 2026-09-05.</p><h2 id="a-removed-facet-kept-looking-active" tabindex="-1">A removed facet kept looking active <a class="header-anchor" href="#a-removed-facet-kept-looking-active" aria-label="Permalink to &quot;A removed facet kept looking active&quot;">​</a></h2><p>Toggling a filter off in More Filters left its facet wearing FilterItem&#39;s <code>--open</code> palette — highlighted, but with no tick. It alternated, which is why it only appeared every other time: FilterItem toggles <code>--open</code> on every trigger click, so the add left it on and the remove cleared it, or the other way round depending on where the sequence started.</p><p><code>markFacet</code> now clears <code>--open</code> and <code>aria-expanded</code> on both paths. A facet is a BUTTON, not a chip with a picker of its own — it should never carry that state at all, whichever way it is being toggled.</p><p>Verified across four consecutive toggles: every removed state is identical to the initial one, class, background and border.</p><h2 id="more-filters-is-listed-alphabetically" tabindex="-1">More Filters is listed alphabetically <a class="header-anchor" href="#more-filters-is-listed-alphabetically" aria-label="Permalink to &quot;More Filters is listed alphabetically&quot;">​</a></h2><p>Forty-eight facets is a list you scan for a name, not one you read, so the panel sorts them (designer, 2026-09-18).</p><p>A COPY is sorted for display. <code>config.moreFilters</code> keeps its own order, which is provenance — the order the live screen declares its filters — and the added set is looked up by name, so the sort changes nothing but the reading order.</p><p>Side effect worth knowing: the overflow default (Order Owner, the sixth filter the live Simple Search shows) no longer heads the panel. It sits under O with everything else.</p><h2 id="catalogue-item-uses-the-multi-select-table" tabindex="-1">Catalogue Item uses the Multi Select Table <a class="header-anchor" href="#catalogue-item-uses-the-multi-select-table" aria-label="Permalink to &quot;Catalogue Item uses the Multi Select Table&quot;">​</a></h2><p>Designer, 2026-09-18: a flat checkbox list was the wrong widget. The live picker is paged and letter-filtered with its own Catalogue ID / Payment Method / Zone sub-filters, so an item needs more than a name to tell two apart.</p><p>Now <code>type: &#39;multi-select-table&#39;</code> — FilterDropdowns Type=Multi Select Table (3039:5624), verified against the Figma screenshot: 640px card, four facet chips (Name / Catalogue Group / Catalogue Item Code / Payment Method), a Datatables body with Name / Catalogue ID / Zone and a row-link column, Apply.</p><p>TODO(backend:Listing): the four sub-filter chips are visual only.</p><p><strong>The table&#39;s facet chips are not bar filters.</strong> They are FilterItems inside a picker, and FilterBar&#39;s add-filter click was scoped to any <code>.filter-bar__panel .filter-item</code> — so clicking &quot;Name&quot; in this card would have put a Name filter on the bar. Scoped to <code>.filter-dropdowns--more</code> now.</p><p><strong>Values come from <code>data-row-value</code></strong>, read before the generic checkbox branch: that branch looks for a <code>.checkbox__label-text</code>, which a table row does not have, and would have come back empty.</p><p>Measured: two rows selected gives &quot;Annual Membership, Quarterly Pass&quot; and 47 matching orders; select-all ticks all six and returns the full 140.</p><h2 id="catalogue-item-picker-real-data-working-sub-filters-responsive" tabindex="-1">Catalogue Item picker: real data, working sub-filters, responsive <a class="header-anchor" href="#catalogue-item-picker-real-data-working-sub-filters-responsive" aria-label="Permalink to &quot;Catalogue Item picker: real data, working sub-filters, responsive&quot;">​</a></h2><h3 id="real-data" tabindex="-1">Real data <a class="header-anchor" href="#real-data" aria-label="Permalink to &quot;Real data&quot;">​</a></h3><p>Name and Catalogue ID are the REAL CatalogueItem table from Affino&#39;s own affino.com instance — all 42 rows, supplied 2026-09-18. Affino&#39;s own store rather than a client&#39;s, deliberately, since this is heading into a prototype.</p><p><strong>Catalogue ID is operator-entered free text</strong>, not a composed string. The real values are <code>CRZAF5001</code>, <code>1</code>, <code>444</code>, <code>Cat ID</code>, <code>glass-3</code>, <code>1243264364326</code> — someone typed &quot;Cat ID&quot; into the field. Figma&#39;s <code>affino-ai-123-0-4</code> is an invented shape and using it would have misrepresented the column. Duplicate names are real and normal too: Glass v2…v6, &quot;Affino Social&quot; twice, one course under both Zen-1 and Zen-2 — which is precisely why this picker is a table and not a list of names.</p><p>The orders&#39; <code>catalogueItem</code> values are drawn from this same catalogue, so picking an item actually matches orders. They were mock names before, and the filter found nothing.</p><p><strong>Zone is NOT real per row</strong> and is flagged as such in the config. The picker derives it through a five-table chain (item → SKC → article or media item → section → channel → zone) that cannot be run from here; these are real zone NAMES spread across the rows so the sub-filter has something to bite on. Group and payment methods are invented — the picker matches them by name but no membership data was available.</p><h3 id="sub-filters" tabindex="-1">Sub-filters <a class="header-anchor" href="#sub-filters" aria-label="Permalink to &quot;Sub-filters&quot;">​</a></h3><p>All four are <strong>free text</strong>, each a substring match. Two corrections this carried, both of which I had guessed wrong:</p><ul><li><strong>&quot;Name&quot; is a text box, not an A–Z strip.</strong> The underlying param is called <code>Letter</code>, which is only a variable name.</li><li><strong>&quot;Payment Method&quot; here is a text box</strong>, matching the method&#39;s name. It is NOT the Payment Method multi-select modal used from the Orders bar — a different lookup entirely. Same words, two different controls.</li></ul><p>Each chip opens its own picker, the same gesture as a chip on the bar. <strong>A chosen row survives the sub-filters</strong>: filtering after choosing must not hide what you chose, which is what the live picker&#39;s second query is for.</p><p>Only <strong>Name and Zone</strong> carry a sort control; Catalogue ID is displayed but is not a sort key.</p><h3 id="one-thing-not-built-deliberately" tabindex="-1">One thing NOT built, deliberately <a class="header-anchor" href="#one-thing-not-built-deliberately" aria-label="Permalink to &quot;One thing NOT built, deliberately&quot;">​</a></h3><p><strong>The live picker has no paging.</strong> It runs 20 rows with an N+1 probe for &quot;there is more&quot; — no offset, no cursor. Narrowing the sub-filters is the only navigation there is. Our picker scrolls the whole 42 instead. Adding a pager would show something the engine cannot currently do, so it is a design decision rather than a fidelity detail — raised with Mark rather than assumed.</p><h3 id="responsive-1" tabindex="-1">Responsive <a class="header-anchor" href="#responsive-1" aria-label="Permalink to &quot;Responsive&quot;">​</a></h3><p>The card is <code>min(var(--ai-size-10), 100cqi)</code> and establishes its own container, so the table responds to the CARD&#39;s width rather than the page&#39;s — what fits in the card is a different question from what fits on screen. Zone drops below 520px, Catalogue ID below 380px; Name never drops, or the picker is a list of codes. Measured inside the bar at 1700 / 1100 / 820 / 620px pages.</p><h2 id="a-sub-filter-does-not-close-its-picker" tabindex="-1">A sub-filter does not close its picker <a class="header-anchor" href="#a-sub-filter-does-not-close-its-picker" aria-label="Permalink to &quot;A sub-filter does not close its picker&quot;">​</a></h2><p>Applying a sub-filter narrows the table and leaves the sub-picker open. Narrowing is an iteration — try a term, see what comes back, adjust — and closing the control after each attempt makes the user re-open it to make the next one. The result is behind it and updates live. It closes on a click elsewhere in the card, like any picker.</p><p>The OUTER picker&#39;s Apply still closes, because that one commits.</p><h2 id="the-column-fit-was-measuring-the-wrong-table" tabindex="-1">The column fit was measuring the wrong table <a class="header-anchor" href="#the-column-fit-was-measuring-the-wrong-table" aria-label="Permalink to &quot;The column fit was measuring the wrong table&quot;">​</a></h2><p>A Multi Select Table picker contains a <code>.datatables</code> of its own, and it lives in the FILTER BAR — which comes first in the DOM. So <code>root.querySelector(&#39;.datatables__body&#39;)</code> returned the PICKER&#39;s body the moment a Catalogue Item chip existed, and <code>fitColumns</code> measured against it: 623px with the picker open, 0 with it closed. The listing collapsed from nine columns to six, with the slack pooling in whichever column could take it.</p><p>It only showed after the picker&#39;s Apply, because that is when <code>renderResults</code> next runs — which made it look like Apply was filtering the main table when it was not. The counts were right throughout; only the columns were wrong.</p><p>Every lookup now goes through <code>listingTable(root)</code>, anchored on <code>[data-listing-body]</code> — the one thing only the listing&#39;s table has. The same trap caught my own test script, which is a fair sign of how easy it is to hit.</p><p>Sibling of the <code>own()</code> fix in FilterDropdowns: once a component can appear inside another instance of itself, a descendant query is no longer a safe way to find &quot;my&quot; element.</p><h2 id="contact-lists-uses-the-multi-select-table-too" tabindex="-1">Contact Lists uses the Multi Select Table too <a class="header-anchor" href="#contact-lists-uses-the-multi-select-table-too" aria-label="Permalink to &quot;Contact Lists uses the Multi Select Table too&quot;">​</a></h2><p>Designer, 2026-09-18. The second picker on this screen to become a table, and it is worth saying why it is one, because the reason is not Catalogue Item&#39;s. There, a name is ambiguous (Glass v2…v6, &quot;Affino Social&quot; twice) and the code disambiguates it. Here the names are unique — but long, near-duplicate and untidy, and a flat list of them cannot be read:</p><ul><li>&quot;Think Tanks 2021&quot;, &quot;Think Tanks 2021 - Messaging&quot; and &quot;Think Tank 2021 - Messaging - Attendees&quot; are three different lists, and the third is <em>Tank</em>, singular.</li><li>The three 2019 Innovation Briefing download lists differ only after 40 characters.</li><li>The longest name is 78 characters, so the Name column WRAPS. Truncating it would collapse exactly the rows a user is trying to tell apart.</li></ul><h3 id="real-data-1" tabindex="-1">Real data <a class="header-anchor" href="#real-data-1" aria-label="Permalink to &quot;Real data&quot;">​</a></h3><p>The whole <code>ContactList</code> table from Affino&#39;s own affino.com instance (Comrz), read from <code>MultipleLookup.cfm</code>&#39;s <code>ContactLists</code> case, lines 6128–6178. <strong>Two columns is the entire table there</strong> — Name and Created. No owner, no member count, no code column. The query joins nothing, so unlike Catalogue Item there is no derived column standing in for something that cannot be run from here.</p><p><strong>71 of 72 lists.</strong> Code 96 &quot;Affino Team (2019) ID: 2&quot; is <code>SystemYN = 1</code>, and the query excludes system lists on BOTH branches of its union — auto-created lists are never selectable. That is also the answer when a list exists in the CRM but cannot be found in this picker.</p><p><strong>Names render verbatim, whitespace included.</strong> &quot;Prospects&quot; carries three trailing spaces and &quot;Core50 170215&quot; one; nothing trims them, so they sort and match as typed. Trimming on render would make two distinct lists look like one. Same rule for the double space in &quot;Breakfast Briefing Sept 2017&quot; and the &quot;Donwloads&quot; typo in code 87 — production data, not something to tidy.</p><p>Orders carry a <code>contactList</code> drawn from this same set, so picking a list actually narrows the listing.</p><h3 id="sub-filters-two-and-one-is-a-toggle" tabindex="-1">Sub-filters: two, and one is a toggle <a class="header-anchor" href="#sub-filters-two-and-one-is-a-toggle" aria-label="Permalink to &quot;Sub-filters: two, and one is a toggle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chip</th><th>Control</th><th>Matches</th></tr></thead><tbody><tr><td>Name</td><td>free text</td><td><code>Name LIKE &#39;%…%&#39;</code>, capped at 50 chars</td></tr><tr><td>My Contact Lists</td><td><strong>checkbox</strong></td><td>rows created by the current user</td></tr></tbody></table><p>The toggle is the first sub-filter in this system that is neither text nor a list, so <code>subFilterRows</code> grew a boolean branch: ticked means &quot;only rows where this is true&quot;, not &quot;match this value&quot; — the generic equality branch would have compared the row&#39;s field to the checkbox&#39;s own label text.</p><p><strong>The toggle&#39;s data is shaped like the real thing, and that is the point.</strong> Comrz has only three distinct creators across these 71 lists, split <strong>54 / 14 / 3</strong> (codes 23, 69 and 70 are the three). Which of the other 68 belongs to which of the two big creators was not available, so that assignment is filler — the proportions are what matter, and an even split would have flattered the control. For the creator of 54 the toggle hides 17 rows and leaves a list that still needs the Name box; for the creator of 3 it collapses the picker to three. Nearly a no-op for the person most likely to press it, near-total for everyone else — worth being able to see in the prototype rather than discovering after it ships.</p><p>The legacy screen injects <code>label[for=&quot;MyContactLists1&quot;]{display:none}</code> to hide this checkbox&#39;s own label — a patch around a layout problem, not a design. Ours is labelled properly.</p><h3 id="one-deliberate-divergence" tabindex="-1">One deliberate divergence <a class="header-anchor" href="#one-deliberate-divergence" aria-label="Permalink to &quot;One deliberate divergence&quot;">​</a></h3><p>The live query applies the Name condition to <strong>both</strong> branches of its union, so searching by name there <strong>hides lists you have already ticked</strong>. That is the opposite of the Catalogue Item picker, whose selected rows survive every sub-filter (its second query carries none of them). Both readings were re-checked against the source; the two pickers really do differ, and the asymmetry looks accidental rather than designed.</p><p>This picker keeps the Catalogue Item behaviour: what you have chosen stays visible while you look for the next one. Raised with Mark as &quot;which is right?&quot; rather than reproducing either by default.</p><h3 id="sorting-is-new-—-and-it-was-silently-breaking-the-listing" tabindex="-1">Sorting is new — and it was silently breaking the listing <a class="header-anchor" href="#sorting-is-new-—-and-it-was-silently-breaking-the-listing" aria-label="Permalink to &quot;Sorting is new — and it was silently breaking the listing&quot;">​</a></h3><p>The live query is <code>ORDER BY &quot;Select&quot; DESC, &quot;Created&quot; DESC</code>, hardcoded, with <strong>no sort control on the screen at all</strong>. Name and Created sort here, ascending on the first click (a picker is a lookup, where A–Z is the useful start; the listing starts descending because a date or a value is what you sort it by). The default order is still the live one.</p><p>Wiring it up exposed a bug that had been sitting under Catalogue Item since it was built. Its headers were rendered as <code>.datatables__sort</code> buttons with no <code>data-sort</code> — decorative. But the listing&#39;s sort handler is bound to <code>root</code>, and the picker is inside it, so a click on the picker&#39;s &quot;Name&quot; header read <code>data-sort</code> as <code>null</code>, <strong>cleared the listing&#39;s sort and re-rendered it</strong>. Now the picker&#39;s headers carry <code>data-picker-sort=&quot;&lt;row field&gt;&quot;</code> and sort their own table, and the listing&#39;s handler returns early for anything inside a <code>.filter-dropdowns</code>.</p><p>Same shape as the <code>listingTable()</code> and <code>own()</code> fixes: a component that can contain another instance of a component breaks every &quot;find my element&quot; query that reaches downward.</p><h3 id="columns-are-per-picker-now" tabindex="-1">Columns are per-picker now <a class="header-anchor" href="#columns-are-per-picker-now" aria-label="Permalink to &quot;Columns are per-picker now&quot;">​</a></h3><p><code>PICKER_DROPPABLE</code> hard-coded Name / code / zone. A filter can now name its own <code>tableColClasses</code>, and Contact Lists uses <code>--name</code> + <code>--date</code> — a date is the one cell in this table that must not wrap, since a date broken over two lines reads as two values.</p><h3 id="measured" tabindex="-1">Measured <a class="header-anchor" href="#measured" aria-label="Permalink to &quot;Measured&quot;">​</a></h3><p>71 rows at Name/Created; sorting by Name puts the three 2019 briefing lists first; &quot;think&quot; in the Name box returns exactly the four Think Tank(s) rows; the My Contact Lists toggle returns 54 of 71; picking a row and applying puts it on the chip and narrows the listing to its 2 orders, with the listing&#39;s own sort still on Created.</p><h3 id="not-built-same-as-catalogue-item" tabindex="-1">Not built, same as Catalogue Item <a class="header-anchor" href="#not-built-same-as-catalogue-item" aria-label="Permalink to &quot;Not built, same as Catalogue Item&quot;">​</a></h3><p><code>iMaxRows = 20</code> with an N+1 probe and no offset — the live picker has no paging at all. Nothing new to raise; it is the same design decision already with Mark.</p><h2 id="rows-open-the-pencil-edits" tabindex="-1">Rows open; the pencil edits <a class="header-anchor" href="#rows-open-the-pencil-edits" aria-label="Permalink to &quot;Rows open; the pencil edits&quot;">​</a></h2><p>Designer, 2026-09-18. Two destinations per row, and they are different screens: the row opens the order to <strong>look at</strong>, the pencil opens it to <strong>change</strong>.</p><h3 id="the-edit-icon-is-on-every-row-now-and-borderless" tabindex="-1">The edit icon is on every row now, and borderless <a class="header-anchor" href="#the-edit-icon-is-on-every-row-now-and-borderless" aria-label="Permalink to &quot;The edit icon is on every row now, and borderless&quot;">​</a></h3><p>It was <code>btn btn--secondary btn--icon btn--xs</code> (Figma node 2926:3566) and <code>mobileOnly</code> — so editing an order, a primary action on this screen, was reachable only on a phone. It now renders at every width.</p><p>Borderless because of what sits next to it: the kebab is a bare icon, and a bordered control beside a bare one reads as two different kinds of thing. The pencil takes the kebab&#39;s treatment exactly — same 32px box, same radius, same hover tint — so the two read as one set of row controls. Any change to one belongs on both, which is why the CSS says so next to the rule.</p><p>The <code>--mobile</code> column class went with it. Nothing else was mobile-only, and a class with no rules left behind is a trap for whoever sets <code>mobileOnly: true</code> next and finds it does nothing.</p><h3 id="anchors-not-click-handlers" tabindex="-1">Anchors, not click handlers <a class="header-anchor" href="#anchors-not-click-handlers" aria-label="Permalink to &quot;Anchors, not click handlers&quot;">​</a></h3><p>Both are real <code>&lt;a href&gt;</code>s built by <code>ROUTE.view</code> / <code>ROUTE.edit</code>, and the whole-row click just follows the row&#39;s own link. That is one code path instead of two, and it is what makes the row keyboard-reachable: the order number is a link, so Tab and Enter get to the same place the mouse does. Middle-click opens a tab and hover shows the destination, neither of which a click handler gives you.</p><p>The pencil therefore needs no <code>stopPropagation</code> of its own. The row handler ignores any click that landed on <code>a, button, label, input, select, textarea</code>, which covers the pencil, the select checkbox, the account chip and the kebab&#39;s label in one rule — <strong>a control inside a row owns its click; only the gaps between them belong to the row</strong>. It also bails when there is a text selection, so selecting an order number does not navigate away from it.</p><p>TODO(backend:Listing) <code>listing-row-routes</code>: the hrefs are placeholders (<code>#order/&lt;orderNo&gt;/view</code>, <code>#order/&lt;orderNo&gt;/edit</code>). Swapping the two <code>ROUTE</code> functions is the whole change. Flagged in the manifest: <strong>the pencil should not render for a row the operator may not change</strong> — that is a permission the payload has to carry, not something the template can infer.</p><h3 id="a-clickable-row-has-to-say-so" tabindex="-1">A clickable row has to say so <a class="header-anchor" href="#a-clickable-row-has-to-say-so" aria-label="Permalink to &quot;A clickable row has to say so&quot;">​</a></h3><p>Pointer plus a hover tint, reusing the tint the expanded row and the kebab hover already use, so the table gains a state rather than a new colour. The paired detail row is excluded — it is the expansion of the row above, not a target.</p><h3 id="measured-1" tabindex="-1">Measured <a class="header-anchor" href="#measured-1" aria-label="Permalink to &quot;Measured&quot;">​</a></h3><p>At 1400px the table now shows 8 columns where it showed 7, still filling the body exactly (955/955) with the same data columns — the pencil&#39;s 32px came out of the slack, not out of a column. At 1000px the count is unchanged. Row click → <code>#order/100412/view</code>, pencil → <code>#order/100412/edit</code>, checkbox → neither.</p><h3 id="the-pair-tightened-—-and-a-hover-border" tabindex="-1">The pair, tightened — and a hover border <a class="header-anchor" href="#the-pair-tightened-—-and-a-hover-border" aria-label="Permalink to &quot;The pair, tightened — and a hover border&quot;">​</a></h3><p>Designer, 2026-09-18, two refinements to the pencil/kebab pair:</p><p><strong>Gap.</strong> Default cell padding put <code>--ai-spacing-5</code> on each side of the join — 32px between the two boxes and 48 between the glyphs, which read as two unrelated controls at opposite ends of the row rather than a set. The edit cell&#39;s right padding goes to 0 and the kebab cell&#39;s left padding to <code>--ai-spacing-1</code>, leaving <strong>4px between the boxes and 20px between the glyphs</strong>, with both 32px hit targets intact. The kebab keeps its right padding — that one is the row&#39;s edge, not the gap.</p><p><strong>Hover border.</strong> Both now draw the same line the table draws between its rows, <code>1px solid var(--ai-border-secondary)</code>. The border is <strong>reserved as transparent at rest</strong> rather than added on hover: with <code>box-sizing: border-box</code> the box stays 32px either way, so nothing shifts by a pixel as the pointer crosses it.</p><p>Applied to the kebab as well as the pencil, at component level — they are one set, and a bordered pencil beside an unbordered kebab would undo the reason the pencil lost its border in the first place.</p><p>Measured light and dark: hover border resolves to exactly the row&#39;s own border colour in both (<code>rgb(220,228,232)</code> / <code>rgb(51,65,85)</code>), box still 32×32.</p><p><strong>Harness note.</strong> Both properties are transitioned, and <strong>CSS transitions never advance under <code>--virtual-time-budget</code></strong> — so a headless probe reads the <em>starting</em> value and reports <code>rgba(0,0,0,0)</code> for a hover colour that is perfectly correct in a real browser. Three probes chased a phantom before the <code>*{transition:none}</code> injection showed the real value. Already in the repo&#39;s headless notes; worth the reminder next to a hover rule.</p><h2 id="the-kebab-was-revealing-nothing" tabindex="-1">The kebab was revealing nothing <a class="header-anchor" href="#the-kebab-was-revealing-nothing" aria-label="Permalink to &quot;The kebab was revealing nothing&quot;">​</a></h2><p>Reported 2026-09-21: opening a row&#39;s kebab showed an empty band.</p><p>The detail row was built from <code>col.tier &gt; 1</code>. <strong><code>tier</code> was removed</strong> when the measured greedy fit replaced the tier steps, so the filter matched no column and every detail row had been rendering empty ever since — silently, because an empty <code>&lt;dl&gt;</code> still lays out as a band and looks like a styling problem rather than a missing list.</p><p>The deeper mistake was deciding the list at RENDER time at all. What fits is a function of the container&#39;s width, and that changes with no re-render — docking the CC sidebar is enough. Any list baked in when the rows are built is wrong the moment the fit moves.</p><p>So every labelled column now renders a <code>dt</code>/<code>dd</code> pair, and <code>syncRowDetail</code> decides which are visible, reading the verdict off the HEAD cells:</p><table tabindex="0"><thead><tr><th>Head class</th><th>Meaning</th><th>In the kebab?</th></tr></thead><tbody><tr><td><code>--nofit</code></td><td>no room at this width</td><td><strong>yes</strong> — this is what the kebab is for</td></tr><tr><td><code>--off</code></td><td>switched off in Edit Columns</td><td><strong>no</strong> — the user said they did not want it</td></tr></tbody></table><p>Reading the head rather than recomputing means the detail row cannot disagree with the table it is explaining. It runs at the end of <code>fitColumns</code>, after the correction loop, so it sees the fit that actually survived — and because every path (render, Edit Columns, the ResizeObserver) ends in <code>fitColumns</code>, there is one call site rather than three to keep in step.</p><p>Each pair is wrapped in a <code>display: contents</code> div so the two halves stay in the list&#39;s own grid while the pair toggles as one thing. <code>[hidden]</code> in base.css carries <code>!important</code>, so hiding still beats <code>display: contents</code>.</p><p>When nothing is missing — possible once enough columns are switched off — the panel says so rather than opening empty. Hiding the kebab entirely would be the alternative; it would shift the row&#39;s right edge as the width changes, which seemed the worse trade.</p><p>Measured: at a 955px table, 5 data columns in the row and the other 15 in the kebab; at 655px, 3 and 17. The two sets are complements at both widths, and Account renders as its chip inside the detail list, not as flat text.</p><p><strong>Not verified headlessly:</strong> the resize path. A ResizeObserver never fires for an iframe resize under <code>--virtual-time-budget</code>, so the two widths above are two separate loads. The RO handler calls <code>fitColumns</code>, which is the only thing <code>syncRowDetail</code> depends on.</p><h2 id="the-account-chip-vanished-on-a-hovered-row" tabindex="-1">The account chip vanished on a hovered row <a class="header-anchor" href="#the-account-chip-vanished-on-a-hovered-row" aria-label="Permalink to &quot;The account chip vanished on a hovered row&quot;">​</a></h2><p>Reported 2026-09-21, and a direct consequence of the row hover tint.</p><p><code>.btn--tertiary:hover</code> out-specifies the chip&#39;s contextual border (0,2,0 vs 0,1,0) and sets <code>--ai-btn-tertiary-border-hover</code> — <strong>transparent in every mode</strong>. So hovering the chip removed the only edge it had, and what it fell back to was <code>rgb(242,244,245)</code> against a row tint of <code>rgb(243,246,247)</code>: one to two per channel apart, in both Light and CC. No border, no fill contrast, no chip. Dark was survivable (<code>rgb(71,85,105)</code> on <code>rgb(41,53,72)</code>) but is fixed the same way.</p><p>The chip now holds <code>--ai-border-secondary</code> through hover and focus — the same colour the edit icon and the kebab use, so all three row controls draw one line.</p><h3 id="scoped-to-clickable-rows-not-to-orders" tabindex="-1">Scoped to clickable rows, not to Orders <a class="header-anchor" href="#scoped-to-clickable-rows-not-to-orders" aria-label="Permalink to &quot;Scoped to clickable rows, not to Orders&quot;">​</a></h3><p>Per the designer: this only applies where a row is a target. The scope is a new <code>datatables--rows-clickable</code> modifier rather than <code>--orders</code>, because a row is clickable when something wired it up, not because the table holds orders — and the listing template is meant to serve ~400 screens.</p><p><strong>The class is added by the code that binds the row click</strong>, not written into the HTML. A datatable can then never advertise an affordance it does not have, which is the failure mode a hand-applied class invites. Verified: the listing carries the class and its rows read <code>cursor: pointer</code>; the Datatables component demo carries neither.</p><h3 id="on-verifying-a-hover-rule-headlessly" tabindex="-1">On verifying a <code>:hover</code> rule headlessly <a class="header-anchor" href="#on-verifying-a-hover-rule-headlessly" aria-label="Permalink to &quot;On verifying a `:hover` rule headlessly&quot;">​</a></h3><p>You cannot hover in headless Chrome, and forcing the state with a class tests your own class rather than the cascade. What settles it is enumerating every <code>border-color</code> rule that matches the chip and ranking them: three rules match, and <code>.datatables--rows-clickable .datatables__account-chip:hover</code> carries one more class than <code>.btn--tertiary:hover</code>, so it wins. Worth knowing the distinction — the earlier transition trap on this same pair of icons was a measurement artefact, and this one would have been too.</p><h3 id="the-panel-flows-into-columns" tabindex="-1">The panel flows into columns <a class="header-anchor" href="#the-panel-flows-into-columns" aria-label="Permalink to &quot;The panel flows into columns&quot;">​</a></h3><p>Designer, 2026-09-21. One pair per line made 15 hidden columns a 425px scroll for a row whose point is to be glanced at. The list is now <code>repeat(auto-fill, minmax(var(--ai-size-3), 1fr))</code>.</p><p><strong>No container query, and no chosen breakpoints.</strong> The grid counts the space itself, so the panel is right at every width rather than at the three or four someone picked. Measured: 5 columns at a 1155px table, 4 at 955, 2 at 619 and 555, 1 at 419 — and the panel drops from 425px to 253 at the common desktop width. No horizontal overflow at any of them.</p><p><code>auto-fill</code>, not <code>auto-fit</code>: auto-fit collapses empty tracks, so a row with a single hidden column would stretch that one pair across the whole panel.</p><p>192px is the minimum a pair needs — an uppercase label like PAYMENT METHOD over values such as &quot;Awaiting Payment Confirmation&quot;. Below that the column COUNT changes, never the legibility.</p><p>Two things the restructure needed:</p><ul><li>The pair is the grid item now, not <code>display: contents</code>, and the label sits <strong>above</strong> the value. Side by side, labels could only align within their own column and the panel would read as ragged.</li><li><code>align-self: center</code> on the <code>dt</code> had to be undone. It is correct in the base two-column grid — it centres the label against its value on the same row — but in a stacked pair the cross axis is horizontal, so the same declaration centred every label over its value. Caught in the screenshot, not the measurements, which is the argument for taking one.</li></ul><p>Also <code>white-space: normal</code> on the list: the detail cell is a <code>&lt;td&gt;</code>, and Table.css puts <code>nowrap</code> on every cell, which inherits straight in and would push long values out of a 192px column.</p><p>Scoped to <code>--orders</code> rather than the component, since it changes the Whos Online detail row&#39;s look too. Worth promoting to the component default once the designer has seen it there.</p><p><strong>Tightened, 2026-09-21</strong> — the choice was &quot;line-height to xs&quot; or &quot;drop the pair&#39;s 4px gap&quot;. Neither wholesale: the panel now mirrors the TABLE&#39;s own rhythm, which is what it stands in for.</p><ul><li><strong>Label → <code>--ai-leading-xs</code> (16px), the same as <code>.table thead th</code>.</strong> It was inheriting the CELL&#39;s 20px, which is loose for 12px uppercase, and that was the slack worth taking.</li><li><strong>Value stays at <code>--ai-leading-sm</code> (20px), the same as <code>.table tbody td</code>.</strong> 16px on 14px text is a ratio of 1.14 — too tight for the wrapped lines a 192px column produces from a catalogue item name, and the panel&#39;s whole argument is that long values stay readable.</li><li><strong>The 4px gap went too</strong>, on the designer&#39;s call after seeing it: the label&#39;s own 16px leading already separates it from its value, and the 12px row-gap between pairs is what does the grouping — so the gap inside a pair was only height. (I had argued to keep it as the binding signal; it is not needed once the label&#39;s leading is tight.)</li></ul><p>The row-gap between pairs then went 12px → <strong>16px</strong> (<code>--ai-spacing-5</code>): with nothing inside a pair, that gap is the only thing grouping a label with its value, so it has to be unambiguous.</p><p>Panel 253px → 237px on the leading alone, 221px with the pair gap out, 233px once the row-gap opened up; pair height 40px → 36px. Both leadings are now stated rather than inherited, so the pair keeps its rhythm if the cell&#39;s line-height moves.</p><p><strong>Labels step down with the headers on mobile</strong> (designer, 2026-09-21): the detail <code>dt</code> takes <code>--ai-font-fixed-4xs</code> in the same <code>@container (max-width: 767px)</code> block that steps <code>.table thead th</code> down, so the two cannot drift. They are the same labels — read from behind the kebab rather than across the row — so a panel whose labels stayed 12px while the table&#39;s went to 11px would read as two different kinds of heading. Measured 12/12 at a 955px table and 11/11 at 419px. Container query, not viewport, so it fires when the TABLE narrows — the docked sidebar does that with no window resize.</p><h2 id="mobile-footer" tabindex="-1">Mobile footer <a class="header-anchor" href="#mobile-footer" aria-label="Permalink to &quot;Mobile footer&quot;">​</a></h2><p>See <code>Datatables.figma-notes.md</code> — the pager collapses to &quot;Page 3 of 7&quot; and the count to &quot;1–20 of 140&quot; below a 767px container. The listing&#39;s own part is the markup: &quot;Showing&quot; and &quot;results&quot; are wrapped in <code>.datatables__count-word</code> spans so the container query can drop them, leaving the range and the total, which are the sentence.</p><h2 id="a-floor-under-the-customer-column" tabindex="-1">A floor under the Customer column <a class="header-anchor" href="#a-floor-under-the-customer-column" aria-label="Permalink to &quot;A floor under the Customer column&quot;">​</a></h2><p>Asked 2026-09-21, after the pencil column narrowed Customer by ~36px.</p><p>Customer is the only column that can grow, so auto table layout takes all its slack from there. Measured with no floor: it sat at <strong>124–163px at every desktop width</strong>, and the NAME truncated on <strong>half the rows</strong> — &quot;Michael Thompson&quot; as &quot;Michael Th…&quot;. The row&#39;s job is to identify a record; the role line beneath can truncate, the name cannot.</p><p><code>min-inline-size: var(--ai-size-3)</code> (192px) on the fluid column. 192 is what the cell needs: 24px avatar + 12px gap + ~124px for the longest name here + 32px of cell padding. A floor, not a width — Customer still takes the slack above it, up to its 240px preference.</p><h3 id="the-cost-measured-rather-than-assumed" tabindex="-1">The cost, measured rather than assumed <a class="header-anchor" href="#the-cost-measured-rather-than-assumed" aria-label="Permalink to &quot;The cost, measured rather than assumed&quot;">​</a></h3><p>Where the floor bites, the fit&#39;s correction loop drops the last column instead of squeezing this one:</p><table tabindex="0"><thead><tr><th>Table width</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>740px</td><td>5 cols, names truncating</td><td>4 cols, none truncating</td></tr><tr><td>940px</td><td>5 cols, Customer 163</td><td>4 cols, Customer 240</td></tr><tr><td>1040px</td><td>6 cols</td><td>5 cols</td></tr><tr><td>1240px</td><td>7 cols</td><td>6 cols</td></tr></tbody></table><p>Zero truncated names at every width afterwards, no horizontal scroll, and the table still fills its body exactly — no dead space.</p><h3 id="an-option-that-was-tried-and-is-worse" tabindex="-1">An option that was tried and is worse <a class="header-anchor" href="#an-option-that-was-tried-and-is-worse" aria-label="Permalink to &quot;An option that was tried and is worse&quot;">​</a></h3><p>Making 192 the PREFERENCE as well as the floor keeps the same column counts but pools the freed slack into the snug columns — Order Status reached 333px and Account 270px — and 2 of 10 names still truncated, because zero truncation needs about 240. Rejected: same cost, worse result.</p><h3 id="and-the-floor-comes-off-when-the-table-is-narrow" tabindex="-1">…and the floor comes off when the table is narrow <a class="header-anchor" href="#and-the-floor-comes-off-when-the-table-is-narrow" aria-label="Permalink to &quot;…and the floor comes off when the table is narrow&quot;">​</a></h3><p>Reported 2026-09-21: the kebab disappeared at the tight end. The floor was the cause — at a 390px viewport the table stood at 370px inside a 309px body and pushed the kebab off the right-hand edge.</p><p>Removed below a <strong>400px table</strong>, not lowered: no fixed floor survives the bottom of the range, since at 320px there are 61px left for Customer after the other four columns.</p><p><strong>400px, deliberately not the 767px the other narrow rules use.</strong> Measured, the floor is safe down to a 419px table and only clips at 349 and below. Keyed to 767 the override also fired on a DESKTOP with the sidebar docked — a 1000px window leaves a 555px table, narrow by container terms but with room to spare — and names truncated there for nothing. The threshold belongs where the damage starts, not where the mobile layout starts.</p><p>The trade inverts on a phone, which is what makes this the right call rather than a compromise: wide, the name matters more than one more column; narrow, the kebab is the only route to the other eighteen columns, and a truncated name is still a name — the row is clickable either way.</p><table tabindex="0"><thead><tr><th>Viewport</th><th>Table</th><th>Kebab</th><th>Names truncating</th></tr></thead><tbody><tr><td>320</td><td>239</td><td><strong>clipped</strong></td><td>5/10</td></tr><tr><td>360</td><td>279</td><td>visible</td><td>5/10</td></tr><tr><td>390</td><td>309</td><td>visible</td><td>4/10</td></tr><tr><td>430</td><td>349</td><td>visible</td><td>0/10</td></tr><tr><td>500–1700</td><td>419–1255</td><td>visible</td><td>0/10</td></tr></tbody></table><p>320px still clips, and cannot not: the table&#39;s min-content is 279px in a 239px body, so it scrolls. That is the intrinsic minimum of five columns, not the floor.</p><p><strong>The override is its own container block, immediately after the rule it overrides.</strong> A container query does NOT raise specificity, so written up with the other narrow rules it tied with the floor and lost on source order — and that failure is invisible: the measurements came back showing Customer still at 192 with the rule apparently in force.</p><h2 id="edit-columns-is-desktop-only" tabindex="-1">Edit Columns is desktop-only <a class="header-anchor" href="#edit-columns-is-desktop-only" aria-label="Permalink to &quot;Edit Columns is desktop-only&quot;">​</a></h2><p>Designer, 2026-09-21. There is nothing for it to do on a phone: the fit is down to the two columns that identify a row, everything else is already behind the kebab, and the panel is a 240px drag-and-drop list — choosing and REORDERING columns is a desktop task on a desktop-sized table. The toolbar keeps the page-size control, which means something at any width.</p><h3 id="a-deliberate-media-against-the-house-rule" tabindex="-1">A deliberate <code>@media</code>, against the house rule <a class="header-anchor" href="#a-deliberate-media-against-the-house-rule" aria-label="Permalink to &quot;A deliberate `@media`, against the house rule&quot;">​</a></h3><p>The first cut keyed this to the datatable&#39;s own container at 767px, like every other narrow rule here. That was wrong for this one control, and the flag I raised became the answer: with the SidebarMenu docked, a <strong>1024px laptop leaves a 557px table</strong>, so the button vanished on a machine whose owner is perfectly able to use it (designer, 2026-09-21).</p><p>The container asks <em>is there room</em>. This rule asks <em>what is the person working on</em> — a device question, which CLAUDE.md §4a names as the one case a viewport query is right for. A laptop keeps its column editor however the sidebar is docked; a phone never has one.</p><p><code>@media (max-width: 1023px)</code>. Measured: hidden at 390 / 768 / 1000 / 1023, shown from 1024 up, and the 240px right-anchored panel sits inside the table at every width above that — including the 581px table a docked 1024px laptop produces.</p><h2 id="the-pencil-is-off-below-a-laptop-—-temporary" tabindex="-1">The pencil is off below a laptop — TEMPORARY <a class="header-anchor" href="#the-pencil-is-off-below-a-laptop-—-temporary" aria-label="Permalink to &quot;The pencil is off below a laptop — TEMPORARY&quot;">​</a></h2><p>Designer, 2026-09-21, to look at: <strong>it may come back</strong>, and one <code>@media</code> block in <code>Datatables.css</code> is the whole change.</p><p>The case for dropping it: it costs 48px on a 311px table, the row itself already opens the record, and the kebab beside it is the only route to the other eighteen columns.</p><p>It also bought back the one width that still overflowed. <strong>At a 320px viewport the table now fits its body</strong> — 239px of table in a 239px body — where before it was 279px and pushed the kebab off the edge. Every width from 320 up now shows the kebab with zero dead space.</p><p><code>@media (max-width: 1023px)</code>, the same floor as Edit Columns, because &quot;mobile&quot; is a device and not a narrow table. Keyed to the table&#39;s own container this would have gone missing on a 1024px laptop with the sidebar docked (a 579px table) — the exact trap the Edit Columns rule had to be corrected for a few minutes earlier.</p><h3 id="a-structural-column-that-hides-no-longer-charges-the-budget" tabindex="-1">A structural column that hides no longer charges the budget <a class="header-anchor" href="#a-structural-column-that-hides-no-longer-charges-the-budget" aria-label="Permalink to &quot;A structural column that hides no longer charges the budget&quot;">​</a></h3><p><code>fitColumns</code> treats the checkbox, pencil and kebab as structure and always adds their width to what is used. A pencil hidden by a media query would still have cost a real column its place at some width. It now checks the column&#39;s computed display before charging for it — read back AFTER the measuring pass, which forces every column visible.</p><h2 id="the-empty-state-did-not-wrap" tabindex="-1">The empty state did not wrap <a class="header-anchor" href="#the-empty-state-did-not-wrap" aria-label="Permalink to &quot;The empty state did not wrap&quot;">​</a></h2><p>Reported 2026-09-21, on a phone and true on a narrow desktop column too: &quot;No orders match the filters you have applied…&quot; ran as one line, ignored its own 320px cap and pushed the table wider than the page.</p><p><code>white-space: nowrap</code> on every <code>.table</code> cell, inheriting into the div inside the <code>colspan</code> cell. The description could not wrap, so its <code>max-width</code> was never reached and the cell&#39;s min-content set the table&#39;s width. The third time this inheritance has bitten in this template, after the row detail list and the picker&#39;s table.</p><p><code>white-space: normal</code> on <code>.cc-listing__empty</code>, and the description&#39;s cap became <code>min(var(--ai-size-6), 100%)</code> — 320px is a MEASURE, not a floor, and 100% keeps it inside a column narrower than that.</p><p>Measured at 360 / 393 / 700 / 1400: wraps at every width, stays centred, and the table no longer exceeds its body. The description is 219px on a 279px table and 320px on a 955px one.</p><h2 id="the-picker-pages-20-at-a-time" tabindex="-1">The picker pages, 20 at a time <a class="header-anchor" href="#the-picker-pages-20-at-a-time" aria-label="Permalink to &quot;The picker pages, 20 at a time&quot;">​</a></h2><p>Designer, 2026-09-21. 20 is the live picker&#39;s own <code>iMaxRows</code> — the one part of its paging worth keeping, since it runs 20 with an N+1 probe and no offset, so &quot;there is more&quot; is all it can say and narrowing the sub-filters is the only way forward. This one can actually go there.</p><p>The pager is the DATATABLE&#39;s footer markup, which buys the listing&#39;s styling and, for free, the collapse to &quot;Page 3 of 4&quot;: that rule keys on the nearest container, and inside this card that IS the card, so a 640px picker gets the compact form without a second rule. It carries <code>data-picker-page</code>, not <code>data-page</code>, so the listing&#39;s own pager handler cannot pick the clicks up. With one page there is no pager at all — <code>:empty</code> hides the row.</p><h3 id="a-selection-has-to-survive-paging" tabindex="-1">A selection has to survive paging <a class="header-anchor" href="#a-selection-has-to-survive-paging" aria-label="Permalink to &quot;A selection has to survive paging&quot;">​</a></h3><p>The bar reads a Multi Select Table by its CHECKED rows, so a row that scrolls out of the DOM takes its selection with it. Rather than add a parallel store to keep in step, <strong>a selected row that is not on this page is rendered hidden</strong> — the selection is still the checked set, exactly as FilterBar expects, and Apply needs no special case.</p><p>That also forced a second rule: once a row has been ticked, the card is the source of truth for what is selected, not the chip&#39;s applied values. Without it the first redraw after a tick — paging, sorting, a sub-filter — would read back the applied set and silently undo the tick.</p><p>Page resets to 1 whenever the list changes underneath it: a sort, a sub-filter applied, a sub-filter cleared. Page 3 of a different list is a different page.</p><p>Measured on Contact Lists (71 rows): 4 pages of 20, &quot;1–20 of 71&quot; beside &quot;Page 1 of 4&quot;; a row ticked on page 1 survives to page 3 and applies correctly; narrowing to &quot;affino&quot; gives 2 pages and resets to the first; clearing restores 4.</p><h2 id="localstorage-for-the-demo" tabindex="-1">localStorage, for the demo <a class="header-anchor" href="#localstorage-for-the-demo" aria-label="Permalink to &quot;localStorage, for the demo&quot;">​</a></h2><p>TODO(backend:Listing) <code>listing-column-prefs</code> / <code>listing-default-filters</code>: saved views and the column layout belong to the user and the server, and both are already in the manifest. localStorage stands in so the prototype survives a reload — a demo that forgets what you set up two clicks ago cannot be walked through. Per browser, not per user, and not shared between devices.</p><p>One key per screen, <code>affino.listing.&lt;screen&gt;</code>, holding the saved views and the column layout.</p><ul><li><strong>Every call is wrapped.</strong> Storage throws in a private window and can be switched off entirely; a screen that will not render because it could not read a preference is a worse failure than one that forgets it.</li><li><strong>Views are keyed by NAME</strong>, not by the row element the in-memory map uses — an element does not survive a reload, and a name is what the user typed and what the endpoint will key on. Duplicate names collapse to one entry; the bar allows them, and last-saved-wins beats inventing a second identity scheme for a demo store.</li><li><strong>Columns are restored before the first paint</strong>, so the table is never drawn in one layout and rearranged into another.</li><li><strong>A column added to the screen since the layout was saved still appears.</strong> The stored order is applied first, then anything it does not mention — a stale preference that hid new data is exactly what makes people distrust saved layouts. Hidden keys that no longer exist are dropped on the way in.</li></ul><h3 id="two-events-the-filterbar-had-to-start-dispatching" tabindex="-1">Two events the FilterBar had to start dispatching <a class="header-anchor" href="#two-events-the-filterbar-had-to-start-dispatching" aria-label="Permalink to &quot;Two events the FilterBar had to start dispatching&quot;">​</a></h3><p>The bar owns the view ROW; this screen owns what a row means. Deleting or renaming was DOM-only, so the store would have kept views the bar no longer showed. <code>filter-bar:delete-view</code> and <code>filter-bar:rename-view</code> now say so, and <code>root.addSavedView(name)</code> puts a persisted view back — doing the icon and row-menu wiring itself, because a caller that had to know about those would be holding half the pattern.</p><p>Measured across a real reload: a hidden column and a saved view both come back, selecting the restored view puts its filter back on the bar, and deleting it empties the store.</p><h1 id="articles-—-the-second-screen-on-this-template" tabindex="-1">Articles — the second screen on this template <a class="header-anchor" href="#articles-—-the-second-screen-on-this-template" aria-label="Permalink to &quot;Articles — the second screen on this template&quot;">​</a></h1><p>Built 2026-09-21. <code>Articles.html</code> + <code>listing-data-articles.js</code>; the template, its CSS and its JS are the Orders ones untouched except for the two knobs below. Adding a listing screen really is adding a config.</p><h2 id="what-came-from-where" tabindex="-1">What came from where <a class="header-anchor" href="#what-came-from-where" aria-label="Permalink to &quot;What came from where&quot;">​</a></h2><p><code>/control/media-items</code> is ControlProfileCode <strong>461</strong>, under Media, security code 94, template <code>/AfcMediaLibrary/CC/MediaItems.cfm</code>. It is not a &quot;cc2&quot; screen — and unlike all three siblings it does not use the generic <code>ControlSearch</code> module either. It hand-rolls a three-row search form, so the form markup <em>is</em> the filter catalogue.</p><table tabindex="0"><thead><tr><th>File</th><th>Gives</th></tr></thead><tbody><tr><td><code>MediaItems.cfm</code></td><td>the 16-control search form</td></tr><tr><td><code>MediaInbox.cfm</code></td><td>the Listing layout&#39;s <code>CProperties</code>, <code>CMethods</code>, paging, sort</td></tr></tbody></table><p>Real: the six columns and their order, all sixteen filters with their control types and option lists, the Media Type groupings, the three MediaTemplate styles, the page sizes, the absence of header sorting, the default order, and all 50 rows. Not real: the thumbnail <strong>images</strong>, and the Topics tagging.</p><h2 id="two-things-the-live-screen-already-has" tabindex="-1">Two things the live screen already has <a class="header-anchor" href="#two-things-the-live-screen-already-has" aria-label="Permalink to &quot;Two things the live screen already has&quot;">​</a></h2><p>Unlike Orders, Articles <strong>already pages server-side against a real total</strong> (<code>row_number() OVER(…)</code>, not <code>SELECT TOP 500</code>) and <strong>already has a working Edit Columns with drag-reorder</strong>. On this screen those are not new capabilities the prototype proposes — they are existing ones it re-dresses. Worth knowing before anyone repeats the Orders framing.</p><h2 id="sorting-no-whitelist-and-that-is-the-finding" tabindex="-1">Sorting: no whitelist, and that IS the finding <a class="header-anchor" href="#sorting-no-whitelist-and-that-is-the-finding" aria-label="Permalink to &quot;Sorting: no whitelist, and that IS the finding&quot;">​</a></h2><p>Orders gates <code>hs</code> to seven values. Articles has nothing equivalent — whatever the client sends as <code>SOColumn</code> is wrapped in quotes and interpolated into the <code>ORDER BY</code>, unvalidated. So every data column carries a <code>sort</code> token here, which is fidelity rather than laxity. Default is <code>PublishStart DESC</code>.</p><h2 id="the-five-chips" tabindex="-1">The five chips <a class="header-anchor" href="#the-five-chips" aria-label="Permalink to &quot;The five chips&quot;">​</a></h2><p>The live screen&#39;s first FOUR in declaration order — Title, Zone, Channel, Section — then <strong>Presentation Style promoted from sixth</strong> (designer, 2026-09-21). Multi-displayed, which sits fifth live, moves into More Filters.</p><p>Two control choices deliberately differ from the live screen, on the distribution rather than on taste:</p><ul><li><strong>Section is a table picker.</strong> 216 distinct sections across 3,570 articles, top ten holding 63% and the other 206 averaging 6.4 each. A select with 216 options is the wrong control; the live screen opens a lookup for the same reason. The picker shows the article count beside the name, which is what tells two similar sections apart.</li><li><strong>Creator is a multi-select, where the live screen uses a type-ahead.</strong> 22 distinct authors — at that size a list is legible and shows people the whole set. Same control family as Section, opposite verdict, and the distribution is what separates them.</li></ul><p><code>Articles Per Screen</code> is NOT a chip: it is the page-size control, which this template already carries in the toolbar. Shipping both would be two controls for one setting. Note the live screen disagrees with itself — the filter offers 10/20/50/100/300 and its DataTables <code>lengthMenu</code> offers 100/50/25/10; the toolbar follows the filter&#39;s list, which is the one an operator sees.</p><h2 id="the-two-template-knobs-articles-needed" tabindex="-1">The two template knobs Articles needed <a class="header-anchor" href="#the-two-template-knobs-articles-needed" aria-label="Permalink to &quot;The two template knobs Articles needed&quot;">​</a></h2><p>Both are per-screen, both default to the Orders behaviour, and both came from a measurement rather than a preference.</p><p><strong>1. <code>truncate</code> — a cap without snug&#39;s sizing.</strong> Title is FLUID: it takes the slack the way Orders&#39; Customer does. But it is free text, and one 84-character title measured <strong>436px</strong> at max-content and ate two columns&#39; worth of budget on its own — the table showed two columns at 1400px. A column can now be snug, truncating, or both. The cap is 240px (the fluid column&#39;s own preferred width, so the two agree), dropping to 128 below a 560px table.</p><p><strong>2. <code>identityColumns</code>.</strong> The fit always shows the leading columns even if they do not fit, because a table of anonymous values is worse than one that scrolls. Orders&#39; two are an order number and a name, which fit a phone together. Articles&#39; two would be Title and Section — both long text — and forcing both overflowed a 309px table by 31px, pushing the KEBAB off the edge: the one control that reaches the other columns. Articles declares <code>identityColumns: 1</code>.</p><h2 id="measured-2" tabindex="-1">Measured <a class="header-anchor" href="#measured-2" aria-label="Permalink to &quot;Measured&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Content column</th><th>Cards per row</th><th>h-overflow</th></tr></thead><tbody><tr><td>1155</td><td>6</td><td>0</td></tr><tr><td>755</td><td>4</td><td>0</td></tr><tr><td>555</td><td>3</td><td>0</td></tr><tr><td>428 / 399</td><td>2</td><td>0</td></tr><tr><td>309</td><td>1</td><td>0</td></tr></tbody></table><p>Both views verified switching back and forth: the table hides and the grid shows and vice versa, Edit Columns hides in grid (there are no columns), and the Section picker still opens with its 17 rows while in grid view. The other three screens re-measured at six widths — identical column counts, no overflow, no right-edge gap.</p><h1 id="the-selection-bar-shared-by-all-four-screens" tabindex="-1">The selection bar, shared by all four screens <a class="header-anchor" href="#the-selection-bar-shared-by-all-four-screens" aria-label="Permalink to &quot;The selection bar, shared by all four screens&quot;">​</a></h1><p>Built 2026-09-22. One bar, one selection model, and the <strong>actions are per-screen config</strong> (<code>bulkActions</code>) read from each live screen&#39;s own declaration — because they are not the same shape, and two of the four disagree about whether selection means anything at all.</p><h2 id="still-orders-classed-in-the-markup" tabindex="-1">Still Orders-classed in the markup <a class="header-anchor" href="#still-orders-classed-in-the-markup" aria-label="Permalink to &quot;Still Orders-classed in the markup&quot;">​</a></h2><p>The datatable keeps <code>datatables--orders</code>. Every listing rule in <code>Datatables.css</code> is scoped to it, so the class is doing double duty as &quot;the listing datatable Type&quot;. That is the right call today — Mark&#39;s instruction was to use the Orders datatable — but the class wants renaming to something like <code>--listing</code> the first time a second Type genuinely diverges.</p><h2 id="the-listing-table-is-fixed-layout-now" tabindex="-1">The listing table is fixed-layout now <a class="header-anchor" href="#the-listing-table-is-fixed-layout-now" aria-label="Permalink to &quot;The listing table is fixed-layout now&quot;">​</a></h2><p>Designer&#39;s call, 2026-09-21, after two bugs on Articles that were the same bug: the Section column flickered between hidden and shown while resizing below 470px, and there was a wide band of empty space beside every title on a phone (measured 121px at a 309px table).</p><p>Both came from one fact: under <code>table-layout: auto</code> a cell can always widen its own column. Everything downstream followed from it —</p><ol><li>An 84-character title demanded <strong>436px</strong> at max-content and left two columns on a 1400px screen.</li><li>The cap that stopped it then left the space, because the column is FLUID and takes the slack while the capped text cannot use it.</li><li>The cap was container-dependent, so the fit and the cap chased each other across a resize — the flicker.</li></ol><p><strong><code>table-layout: fixed</code> removes the cause.</strong> Content can no longer affect a column, so text ellipsises at whatever width the fit gave it. The measuring pass still runs at <code>max-content</code> — that is where the fit learns what each column WANTS — and only the render is fixed. Scoped to <code>--orders</code>, so the Multi Select Table pickers keep auto layout; their widths are content-driven by design.</p><h3 id="the-fit-now-decides-widths-not-just-visibility" tabindex="-1">The fit now decides widths, not just visibility <a class="header-anchor" href="#the-fit-now-decides-widths-not-just-visibility" aria-label="Permalink to &quot;The fit now decides widths, not just visibility&quot;">​</a></h3><p><code>sizeColumns</code> writes an explicit width per visible column, reading the same three roles the CSS used to express as behaviours:</p><table tabindex="0"><thead><tr><th>Role</th><th>Width</th></tr></thead><tbody><tr><td>hug / structural</td><td>its measured natural</td></tr><tr><td>snug</td><td>its natural, capped at 224px so one long enumerated value cannot take half the table</td></tr><tr><td>fluid</td><td>everything left over, never below its 192px floor</td></tr></tbody></table><p>The rounding remainder goes to the fluid column, so the widths sum to the table exactly. <strong>&quot;No dead space&quot; used to be the browser&#39;s to keep; it is arithmetic now</strong> — which is the real cost of this change and the thing to check first if a gap ever appears at the right-hand edge.</p><h3 id="measured-both-screens" tabindex="-1">Measured, both screens <a class="header-anchor" href="#measured-both-screens" aria-label="Permalink to &quot;Measured, both screens&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>1255</th><th>955</th><th>655</th><th>619</th><th>419</th><th>359</th><th>309</th><th>239</th></tr></thead><tbody><tr><td>Articles cols</td><td>7</td><td>4</td><td>4</td><td>3</td><td>1</td><td>1</td><td>1</td><td>1</td></tr><tr><td>Title slack</td><td>32</td><td>32</td><td>12</td><td>12</td><td>12</td><td>12</td><td>12</td><td>12</td></tr></tbody></table><p>Slack is now cell padding and nothing else — the band is gone. No overflow at any width. Orders re-checked: 4 columns at 955 and 2 at 309 as before, and 4 rather than 3 at 619, because a fixed column no longer has to leave room for what its content might want.</p><p>The flicker is addressed by removing its cause rather than by damping it: there is no container-dependent cap left to chase. That one is reasoned from the mechanism rather than reproduced — a ResizeObserver never fires for an iframe resize under a virtual time budget, so a resize sequence is not something this harness can drive.</p><h3 id="one-css-edit-that-cost-four-rounds" tabindex="-1">One CSS edit that cost four rounds <a class="header-anchor" href="#one-css-edit-that-cost-four-rounds" aria-label="Permalink to &quot;One CSS edit that cost four rounds&quot;">​</a></h3><p>Mid-way through, several measurements made no sense — a span reported <code>display: inline</code> with the rule that sets <code>display: block</code> plainly present in the file. The cause was <strong>a single orphan <code>}</code></strong> left by a programmatic edit: everything after it was dropped by the parser, so <code>.datatables__truncate</code> and every rule below it silently did nothing. Two of the &quot;failed&quot; approaches before it were probably fine.</p><p><code>grep -c &#39;{&#39;</code> against <code>grep -c &#39;}&#39;</code> is a two-second check and would have caught it immediately. Worth doing after any scripted CSS surgery.</p><h3 id="the-fit-was-measuring-its-own-output" tabindex="-1">The fit was measuring its own output <a class="header-anchor" href="#the-fit-was-measuring-its-own-output" aria-label="Permalink to &quot;The fit was measuring its own output&quot;">​</a></h3><p>Reported straight after the switch: resizing just removed columns, one after another, and they never came back.</p><p><code>sizeColumns</code> leaves an inline width on every <code>th</code>. <code>measureColumns</code> then read those back as the columns&#39; &quot;natural&quot; widths — <strong>the pass was measuring its own last output rather than the content</strong>. Every re-fit during a drag therefore started from a narrower table than the one before, shed another column, and had no way to recover when the window widened again.</p><p>One line fixes it: clear the inline widths before the measuring pass. It has to be there rather than at the end of <code>sizeColumns</code>, because the render between the two passes is what the user is looking at.</p><p><strong>Tested for convergence and reversibility</strong>, which is the property that was missing — the same widths walked down and back up must give the same answers:</p><table tabindex="0"><thead><tr><th>Page</th><th>1200</th><th>1000</th><th>800</th><th>600</th><th>500/400</th><th>600</th><th>800</th><th>1000</th><th>1200</th></tr></thead><tbody><tr><td>Articles</td><td>6</td><td>5</td><td>5</td><td>3</td><td>3</td><td>3</td><td>5</td><td>5</td><td>6</td></tr><tr><td>Orders</td><td>6</td><td>5</td><td>5</td><td>3</td><td>2</td><td>3</td><td>5</td><td>5</td><td>6</td></tr></tbody></table><p>Identical on the way back, no overflow at any step.</p><p><strong>The harness note that matters here:</strong> a ResizeObserver does not fire under <code>--virtual-time-budget</code>, so the resize path cannot be driven directly. The test above stands in for it by resizing the page column and then clicking a sort header, which re-renders and re-fits without changing the column set. Without that substitution the probe showed the table simply overflowing by 508px and looked like a different bug entirely.</p><h3 id="second-attempt-three-things-the-first-one-got-wrong" tabindex="-1">Second attempt: three things the first one got wrong <a class="header-anchor" href="#second-attempt-three-things-the-first-one-got-wrong" aria-label="Permalink to &quot;Second attempt: three things the first one got wrong&quot;">​</a></h3><p>Reinstated 2026-09-21 after a rollback. The approach was right; the implementation had three defects, each of which only shows once the widths are ours to write.</p><p><strong>1. The measure looked only at the headers, so the controls were cropped.</strong><code>--measuring</code> was added to the <code>th</code> and not to the body cells, so during the pass the header row had all fourteen columns while the body rows had only the eight that were not <code>--nofit</code>. A table lays out ONE column structure for both, so the eight visible body cells were assigned to the first eight header slots: the kebab&#39;s cell was measured under &quot;Publish Start&quot; and reported 155px, the pencil&#39;s 96px, while their own empty headers reported 16 and 20. Under auto layout the browser quietly corrected for it. Under fixed layout those numbers are the column, and the select, pencil and kebab came out cropped.</p><p>The pass now shows the body cells too, and the measurement takes <code>max(header, body cell)</code> — the header of a structural column is empty, so the content is only ever in the body.</p><p><strong>2. Nothing clamped the sum.</strong> Under fixed layout the table IS the sum of the widths, so a few pixels over is not &quot;slight overflow&quot;, it is a horizontal scrollbar. Excess now comes off the fluid column first, down to its floor, then off the snug columns from the right, which truncate anyway. Measured before: 13–18px over at three widths.</p><p><strong>3. The fluid floor stayed at 192px on a phone.</strong> The CSS rule it replaced lifted that floor below a 400px table; the JS did not, so at 239px the sum of the minima exceeded the table by 88px and the kebab went over the edge — the same control, lost the same way, for a different reason. <code>sizeColumns</code> now mirrors the rule it replaced.</p><p><strong>Verified across both screens</strong> — Articles and Orders, 320px to 1700px: no cropping of the checkbox, pencil or kebab at any width; no overflow and no dead space; the title&#39;s unused space is zero. And the property that was missing the first time, convergence and reversibility:</p><table tabindex="0"><thead><tr><th>Page</th><th>1200</th><th>1000</th><th>800</th><th>600</th><th>450</th><th>350</th><th>450</th><th>600</th><th>800</th><th>1000</th><th>1200</th></tr></thead><tbody><tr><td>Articles</td><td>6</td><td>4</td><td>4</td><td>2</td><td>1</td><td>1</td><td>1</td><td>2</td><td>4</td><td>4</td><td>6</td></tr><tr><td>Orders</td><td>6</td><td>5</td><td>4</td><td>3</td><td>2</td><td>2</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td></tr></tbody></table><p>Symmetric both ways, no overflow at any step.</p><h3 id="opening-the-kebab-panel-narrowed-the-table" tabindex="-1">Opening the kebab panel narrowed the table <a class="header-anchor" href="#opening-the-kebab-panel-narrowed-the-table" aria-label="Permalink to &quot;Opening the kebab panel narrowed the table&quot;">​</a></h3><p>Reported 2026-09-21, once resizing was working. Two causes, both worth fixing.</p><p><strong>The observer fired on HEIGHT.</strong> A ResizeObserver reports any size change, and a table&#39;s height changes constantly — opening a row&#39;s detail panel is the obvious one. It now compares the width and returns early when only the height moved: nothing about a taller table changes what fits across it, so the re-fit was at best wasted work.</p><p><strong>And the measure counted the open panel.</strong> A detail row is a single cell spanning every column, so at <code>max-content</code> it hands its own width demand to all of them — the pass was measuring the panel rather than the columns, and the columns came back narrower than the table. Detail rows are now hidden for the duration of the pass, which also covers anything else that re-fits while one is open.</p><p>Either fix alone would have hidden the symptom; both are real, so both are in. Measured on Articles and Orders at 1400 / 700 / 390: opening and closing the panel leaves the column count and the table width untouched, and the resize walk is still symmetric with the width guard in place.</p><p><strong>…and a third cause, below 1024 only.</strong> The panel still shortened the row on the narrow side. <code>colspan</code> declares how many column slots exist, and the detail cell carried the FULL column count — so opening a panel brought every hidden column back as a real slot, and under fixed layout each one took its assigned width out of the table. Below 1024px, where the device rule hides the pencil, that was a 44px gap at the end of every row. Above it the pencil is visible, which is exactly why the bug lived on one side of that line.</p><p>The detail and empty-state cells now carry the count of columns actually showing, read from the computed display rather than from the fit&#39;s own bookkeeping: three separate things hide a column here — the fit, Edit Columns and a media query — and only the browser knows about all three.</p><p>Measured on both screens at 1400 / 1024 / 900 / 700 / 500 / 390: the row fills the table with a panel open at every one. Empty state still spans the table, and the resize walk is still symmetric.</p><h2 id="header-actions-per-screen" tabindex="-1">Header actions, per screen <a class="header-anchor" href="#header-actions-per-screen" aria-label="Permalink to &quot;Header actions, per screen&quot;">​</a></h2><p>Designer, 2026-09-21: Articles gets the primary <strong>Add</strong> from the CCHeader pattern&#39;s own actions cluster (CC Hybrid <code>4105:3640</code>) — plus icon, the word Add, Primary/Base.</p><p>The listing header has been a bare title since Pass 1, which is what Figma&#39;s listing frames draw, but the pattern has always carried the cluster. So this is not a new element, it is the one the pattern already defines.</p><p><strong>Declared in the screen&#39;s config, not written into the page:</strong><code>headerActions: [{ label: &#39;Add&#39;, icon: &#39;plus&#39;, variant: &#39;primary&#39; }]</code>. The next screen that needs one is a config entry like everything else here, and Orders — which declares none — renders nothing.</p><p><strong>The pattern owns the responsive behaviour.</strong> <code>.cc-header__actions</code> collapses a text+icon button to a 32px icon-only square on a narrow header and hides <code>__btn-label</code> to do it. Measured: 85×40 with the label at 1400px, 32×32 without it at 700 and 390. Nothing to add for that.</p><p>TODO(backend:Listing) <code>listing-header-actions</code>: Add goes nowhere. It wants the screen&#39;s &quot;new record&quot; route — the sibling of <code>listing-row-routes</code>, ideally in the same payload — and the same permission caveat: an operator who may not create should not be shown the button.</p><h1 id="article-archive-—-the-third-screen-on-this-template" tabindex="-1">Article Archive — the third screen on this template <a class="header-anchor" href="#article-archive-—-the-third-screen-on-this-template" aria-label="Permalink to &quot;Article Archive — the third screen on this template&quot;">​</a></h1><p>Built 2026-09-22. <code>ArticleArchive.html</code> + <code>listing-data-article-archive.js</code>. Three knobs were added to the template, all per-screen and all defaulting to the Orders behaviour; the CSS was not touched at all.</p><h2 id="the-five-chips-are-the-catalogue" tabindex="-1">The five chips ARE the catalogue <a class="header-anchor" href="#the-five-chips-are-the-catalogue" aria-label="Permalink to &quot;The five chips ARE the catalogue&quot;">​</a></h2><p>Six filters are declared, and the sixth is not a filter. Order By is assigned straight to the table&#39;s own sort parameter:</p><div class="language-cfml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if( Len(Trim(Form.Order)) AND NOT StructKeyExists(URL,&quot;hs&quot;) ) url.hs = Form.Order;</span></span></code></pre></div><p>So it ships as the sortable column headers this template already has — the same call Articles made for Articles Per Screen, one setting and one control. The house rule (the live screen&#39;s first five) therefore lands exactly on the boundary here rather than cutting anything, and <strong>More Filters is empty</strong>.</p><p>That is a state neither sibling reaches, so the template now <strong>hides the Add Filters chip when the catalogue is empty</strong>. A dashed chip that opens a panel saying nothing is available is worse than no chip. Nothing was invented to fill the panel, which was the alternative and would have put invention next to a faithful catalogue.</p><h2 id="one-chip-reading-another-—-scopedby" tabindex="-1">One chip reading another — <code>scopedBy</code> <a class="header-anchor" href="#one-chip-reading-another-—-scopedby" aria-label="Permalink to &quot;One chip reading another — `scopedBy`&quot;">​</a></h2><p>&quot;Filter by&quot; (Section / Article / Channel, defaulting to Section+Article) is the first control on this template that is <strong>not a row filter</strong>. It decides which fields the Name term is matched against:</p><div class="language-cfml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AND ( 1 = 0</span></span>\n<span class="line"><span>  &lt;cfif ListContains(Form.FilterType,&quot;Section&quot;)&gt; OR &quot;StandardSection&quot;.&quot;Name&quot; LIKE …</span></span>\n<span class="line"><span>  &lt;cfif ListContains(Form.FilterType,&quot;Channel&quot;)&gt; OR &quot;Channel&quot;.&quot;Name&quot;         LIKE …</span></span>\n<span class="line"><span>  &lt;cfif ListContains(Form.FilterType,&quot;Article&quot;)&gt; OR &quot;StandardItem&quot;.&quot;Title&quot;   LIKE …</span></span>\n<span class="line"><span>)</span></span></code></pre></div><p>A filter declares <code>scopedBy</code> (the chip to read) and <code>scopeFields</code> (that chip&#39;s option names → row fields). The <code>1 = 0</code> is reproduced rather than smoothed over: untick every box and a term matches <strong>nothing</strong>, instead of quietly falling back to searching the title. Measured on the eight real rows:</p><table tabindex="0"><thead><tr><th>Name</th><th>Filter by</th><th>Rows</th></tr></thead><tbody><tr><td>—</td><td>Section, Article</td><td>8</td></tr><tr><td>Temp</td><td>Section, Article</td><td>2</td></tr><tr><td>Temp</td><td>Section</td><td>0</td></tr><tr><td>Add</td><td>Channel</td><td>8</td></tr><tr><td>Add</td><td><em>(none)</em></td><td>0</td></tr></tbody></table><p>Chips can <strong>open with a value</strong> (<code>defaultValues</code>), seeded before the FilterBar takes its save-view baseline so the screen does not offer to save the view it opened on. Only <strong>Type</strong> uses it.</p><h3 id="the-screen-must-not-look-filtered-before-anyone-touches-it" tabindex="-1">The screen must not look filtered before anyone touches it <a class="header-anchor" href="#the-screen-must-not-look-filtered-before-anyone-touches-it" aria-label="Permalink to &quot;The screen must not look filtered before anyone touches it&quot;">​</a></h3><p>Designer, 2026-09-22. Both chips originally opened with the live screen&#39;s own defaults — Section+Article and Article — and a screen that arrives already filtered is wrong even when the values are right.</p><p><strong>Type keeps its default</strong>, because Type is a mode rather than a filter: the live screen always holds one, a radio cannot be cleared, and clearing it here produces Articles and Media interleaved — a list the live screen has no way to produce, on a table that shows no Type column to tell them apart.</p><p><strong>&quot;Filter by&quot; loses its visible default</strong>, which costs nothing because it narrows nothing; it only scopes the Name term. But it cannot simply be dropped, or a fresh screen would find nothing the moment a term was typed. The fix is that <strong>unset and empty are different states</strong>, which is what the live screen does too:</p><table tabindex="0"><thead><tr><th>Scope chip</th><th>Means</th><th>Name term matches</th></tr></thead><tbody><tr><td>no value, never touched</td><td><code>&lt;cfparam default=&quot;Section,Article&quot;&gt;</code></td><td>section + title</td></tr><tr><td><code>[&#39;Channel&#39;]</code></td><td><code>ListContains(FilterType,&quot;Channel&quot;)</code></td><td>channel</td></tr><tr><td><code>[]</code>, explicitly emptied</td><td><code>AND (1 = 0 …)</code></td><td>nothing</td></tr></tbody></table><p>So the default moved off the chip and onto the Name filter as <code>scopeDefault</code>. Collapsing the two with a plain <code>|| []</code> is the bug this avoids. Measured: opens on 8 with one chip filled; &quot;Temp&quot; untouched → 2; &quot;Add&quot; scoped to Channel → 8; &quot;Add&quot; with the scope explicitly emptied → 0.</p><p>Note the Name chip is a plain <strong>text</strong> box, not the predictive Articles gives its Title. Not a distribution call — a semantic one: the term hits up to three different fields at once, and a type-ahead offering titles would hide the section and channel matches the same term is finding.</p><h2 id="type-is-an-entity-switch" tabindex="-1">Type is an entity switch <a class="header-anchor" href="#type-is-an-entity-switch" aria-label="Permalink to &quot;Type is an entity switch&quot;">​</a></h2><p>The one thing this screen does that neither sibling does. Type=1 queries <code>StandardItem</code>, Type=26 queries <code>MediaItem</code>, through two near-identical queries with the same six columns. Both row sets ship and the chip picks between them.</p><p>The Media branch is worth showing because it looks nothing like the Article one: names are raw filenames, sections are forum-media buckets, Publish End is publish start <strong>plus ten years</strong>, and there are 3 presentation styles against 63. A column sized to one branch is not sized to the other.</p><p><strong>Known divergence:</strong> live is a radio and always holds exactly one value; this chip can be cleared, which shows both entities at once — a state the live screen cannot reach.</p><h2 id="sorting-there-is-a-whitelist-here" tabindex="-1">Sorting: there IS a whitelist here <a class="header-anchor" href="#sorting-there-is-a-whitelist-here" aria-label="Permalink to &quot;Sorting: there IS a whitelist here&quot;">​</a></h2><p>Worth recording because Articles has none. <code>url.hs</code> goes through a <code>&lt;cfswitch&gt;</code> with seven cases — Title, Alphabetical, Channel, Section, PresentationStyle, CreatedBy, Chronological, PublishEnd — so the <code>sort</code> tokens are the whitelist, not every column.</p><p>And the default is <strong>PublishStart DESC on a column the screen never shows.</strong> The one date it does show is Publish End; the Date Range chip filters PublishStart. The rows ship in PublishStart order and <code>sortRows</code> leaves an unknown token alone, so the screen opens on an order no header can claim — which is exactly what the live screen does.</p><h2 id="rowkey-—-and-the-articles-bug-it-uncovered" tabindex="-1"><code>rowKey</code> — and the Articles bug it uncovered <a class="header-anchor" href="#rowkey-—-and-the-articles-bug-it-uncovered" aria-label="Permalink to &quot;`rowKey` — and the Articles bug it uncovered&quot;">​</a></h2><p>Row identity was hard-coded to <code>orderNo</code>. Articles has no such field, so every Articles row had been shipping:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;datatables__row-edit&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#order//edit&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> aria-label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Edit order &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>— twenty identical, empty controls for a screen reader, on a screen that has been live in the demo since 2026-09-21. The screen now declares <code>rowKey</code>, <code>routeNoun</code> (the URL slug) and <code>rowNoun</code> (what is spoken). Two nouns because they are read by different things: Article Archive&#39;s slug is <code>archived-item</code> and announcing &quot;Edit archived-item 5361&quot; puts a hyphen in the middle of a spoken phrase. Articles was given <code>rowKey: &#39;articleId&#39;</code> in the same pass.</p><h2 id="the-eight-real-rows-are-the-point" tabindex="-1">The eight real rows are the point <a class="header-anchor" href="#the-eight-real-rows-are-the-point" aria-label="Permalink to &quot;The eight real rows are the point&quot;">​</a></h2><p>They are every <code>ArchivedYN = 1</code> item in the 200-row sample the read tools allow — <code>client_db_table_sample</code> caps at 200 and takes no WHERE clause, so the archive&#39;s own query cannot be run from here. They are not what a tidy archive looks like, and that is why they lead the file:</p><ul><li>Every one is <code>Live = 0</code>. Archived content is unpublished content.</li><li>Seven were created by UserCode 3, whose FirstName is <strong>empty</strong> and LastName is &quot;Former Member&quot;. The query builds <code>FirstName + &#39; &#39; + LastName</code>, so the cell really renders with a <strong>leading space</strong>. Kept verbatim — trimming it here would hide exactly the kind of value a column has to survive.</li><li>The titles are &#39;Golf VI&#39;, &#39;Um Bongo&#39;, &#39;Temp Review&#39;, &#39;Temp Test&#39; and &#39;meh&#39;, and two are a record and its copy one second apart. The archive is where test content goes to sit.</li><li>All eight share one section and one channel, both called &quot;Add Review&quot; — which is what makes the scope chip demonstrable, since the same term hits both.</li><li>Their Presentation Style is &#39;Emojo Rated (Deprecated)&#39;; 40 of the 63 StandardTemplates on this instance carry &quot;(Deprecated)&quot; in the name.</li></ul><p>A first theory — that the archive was the five sections named &quot;…Archive&quot; (Branding, News, Quick Smart, Careers, Affino Features), 50 articles between them — was <strong>wrong</strong>, and checking it rather than shipping it is the only reason this file is not 50 rows of confidently mislabelled data. Those are public archive <em>display</em> areas; not one of their articles is flagged archived.</p><h2 id="three-defects-in-the-live-screen-recorded-not-reproduced" tabindex="-1">Three defects in the live screen, recorded not reproduced <a class="header-anchor" href="#three-defects-in-the-live-screen-recorded-not-reproduced" aria-label="Permalink to &quot;Three defects in the live screen, recorded not reproduced&quot;">​</a></h2><ol><li><strong>The total does not match the listing.</strong> The count query runs <code>WHERE ArchivedYN = 1</code>, but the listing&#39;s own WHERE also admits the auto-archived branch — so on a site with more than 500 archived items the footer under-reports. It is also only run when exactly 500 come back.</li><li><strong>The Media branch may be unreachable.</strong> Its second WHERE branch tests <code>ArchivedSectionCode &gt; 0</code>, and every sampled MediaItem has that column NULL; <code>NULL &gt; 0</code> is UNKNOWN in T-SQL. Zero of 200 sampled media items are archived either way.</li><li><strong><code>Trim(Form.FilterTerm) GT 0</code></strong> is a numeric comparison against a string. It happens to behave for most terms because CF falls back to a string compare, but it is <code>Len()</code> that was meant.</li></ol><h2 id="not-built-deliberately" tabindex="-1">Not built, deliberately <a class="header-anchor" href="#not-built-deliberately" aria-label="Permalink to &quot;Not built, deliberately&quot;">​</a></h2><p>The Date Range chip is the <strong>Custom</strong> from/to pair only. Live also offers five presets (Any Time / Today / This Week / Last Week / This Month), and a preset row is a control the FilterBar has no Figma variant for. The vocabulary is kept in <code>ARCHIVE_DATE_PRESETS</code> and the gap carries a <code>TODO(backend:Listing)</code>.</p><h2 id="export-is-per-screen-not-part-of-the-bar" tabindex="-1">Export is per screen, not part of the bar <a class="header-anchor" href="#export-is-per-screen-not-part-of-the-bar" aria-label="Permalink to &quot;Export is per screen, not part of the bar&quot;">​</a></h2><p>Designer, 2026-09-22: <strong>Articles and Article Archive have no Export.</strong> Of the three screens built, only Orders offers one, and the toolbar&#39;s actions vary screen to screen.</p><p>So the split control is not a FilterBar feature that screens opt out of — it is a per-screen action that a screen opts <em>in</em> to by carrying the markup. Removed from <code>Articles.html</code> and <code>ArticleArchive.html</code> outright; <code>ListingScreen.html</code> keeps it. Nothing else had to move: <code>.filter-bar__actions</code> is a plain flex row with a gap and no positional selectors, as its own CSS comment already promised, and no JS reads the export markup — <code>FilterBar.css</code> only styles it when it is there. Verified headless: Orders&#39; toolbar still reads Search · Export · kebab, the other two read Search · kebab, no gap left behind.</p><p><code>listing-export</code> in the manifest and HANDOVER.md is now scoped to Orders.</p><h3 id="the-kebab-went-the-same-way" tabindex="-1">The kebab went the same way <a class="header-anchor" href="#the-kebab-went-the-same-way" aria-label="Permalink to &quot;The kebab went the same way&quot;">​</a></h3><p>Designer, 2026-09-22, right after Export and for the same reason: <strong>only Orders of the three needs it.</strong> Removed from <code>Articles.html</code> and <code>ArticleArchive.html</code>.</p><p>What was in it is worth recording, because it is the clearest example of the pattern this template keeps hitting. <em>Import orders</em> and <em>Generate Shipping Labels</em> are not template chrome that drifted — they are <strong>Figma content</strong>, drawn on the FilterBar&#39;s own frame, which was authored for the Orders listing. <code>FilterBar.figma-notes.md</code> still records measuring &quot;Generate Shipping Labels&quot; for width at Size=sm. Cloning the template carried them onto a screen full of articles, and onto an archive of unpublished 2008 test content.</p><p>Article Archive was worse, and that one was this build&#39;s own doing: the import was <em>relabelled</em> to &quot;Import archived items&quot; rather than questioned. That action does not exist — <code>ArchiveManagementDef.cfm</code> declares <code>CMethods = &quot;list,change,viewonly&quot;</code>, so there is no add and no import. A plausible label is worse than an obviously wrong one, because it reads as researched. Removed rather than relabelled a second time: what those screens really offer has not been read, and until it has, nothing is the honest answer.</p><p>Nothing else had to move — <code>.filter-bar__actions</code> is a plain flex row with a gap and no positional or <code>:last-child</code> selectors, so the two screens are left with the desktop search field alone, collapsing to the search icon below the container breakpoint. Measured at 1500 / 1000 / 700 / 390 on all three: no overflow anywhere, and the <strong>mobile search takeover still works end to end</strong> at 390 with both its neighbours gone — icon → <code>--search</code> mode → exit.</p><h3 id="three-per-screen-things-found-living-in-a-shared-place" tabindex="-1">Three per-screen things found living in a shared place <a class="header-anchor" href="#three-per-screen-things-found-living-in-a-shared-place" aria-label="Permalink to &quot;Three per-screen things found living in a shared place&quot;">​</a></h3><p>Worth naming as a pattern rather than three incidents, because a fourth is likely:</p><table tabindex="0"><thead><tr><th>What</th><th>Where it was</th><th>How it surfaced</th></tr></thead><tbody><tr><td>Row identity (<code>orderNo</code>)</td><td>hard-coded in the renderer</td><td>blank aria-labels on every Articles row</td></tr><tr><td>Export</td><td>markup in the cloned template</td><td>designer spotted it on two screens</td></tr><tr><td>Kebab actions</td><td>Figma content on the shared FilterBar frame</td><td>designer spotted it on two screens</td></tr></tbody></table><p>The shape is always the same: something true of Orders sitting somewhere every screen inherits. Worth a look before the fourth screen, not after.</p><h1 id="media-items-—-the-fourth-screen-on-this-template" tabindex="-1">Media Items — the fourth screen on this template <a class="header-anchor" href="#media-items-—-the-fourth-screen-on-this-template" aria-label="Permalink to &quot;Media Items — the fourth screen on this template&quot;">​</a></h1><p>Built 2026-09-22. <code>MediaItems.html</code> + <code>listing-data-media-items.js</code>. The first screen that is not purely config: it adds two CELL renderers and their CSS, because it is the first with a <strong>thumbnail</strong> and the first whose Type column is a glyph rather than text.</p><h2 id="the-thumbnail" tabindex="-1">The thumbnail <a class="header-anchor" href="#the-thumbnail" aria-label="Permalink to &quot;The thumbnail&quot;">​</a></h2><p><code>--ai-spacing-11</code> (64px) on desktop, <code>--ai-spacing-9</code> (48px) from mobile — the designer&#39;s values, against the live screen&#39;s 60×60, which is off the spacing scale in both directions. <code>@container</code>, and a max-width step rather than a min-width one, because that is what every other responsive rule in <code>Datatables.css</code> does; the value is the designer&#39;s, the direction is the file&#39;s.</p><p><strong>Its header is blank</strong>, because <code>CProperties[1][2]</code> is an empty string. That is not cosmetic — the fit reads a label-less column as <strong>structure</strong>: always drawn, always charged to the budget, never dropped. Which is exactly what a thumbnail wants, and is also the reason for the next paragraph.</p><h3 id="identitycolumns-1-for-a-new-reason" tabindex="-1"><code>identityColumns: 1</code>, for a new reason <a class="header-anchor" href="#identitycolumns-1-for-a-new-reason" aria-label="Permalink to &quot;`identityColumns: 1`, for a new reason&quot;">​</a></h3><p>Because the thumbnail is structural, it is <strong>not an identity column</strong>, so <code>identityColumns</code> starts counting at Title. Setting it to 2 therefore forced Title <em>and Type</em> — measured, that overflowed a 239px table by <strong>207px</strong> and pushed the kebab off the edge, the same failure that gave Articles its 1. With 1, Title is forced and Type becomes droppable.</p><p>Worth recording as the general shape: <code>identityColumns</code> counts LABELLED columns. A screen whose leading column has no header gets one fewer than it looks like it has.</p><h3 id="the-image-is-the-one-thing-that-is-not-real" tabindex="-1">The image is the one thing that is not real <a class="header-anchor" href="#the-image-is-the-one-thing-that-is-not-real" aria-label="Permalink to &quot;The image is the one thing that is not real&quot;">​</a></h3><p>The live screen builds the thumbnail from <code>MediaItem.ImageThumb</code> through an internal DAM path and no read available here returns a usable URL. The first build put a tinted box there; the designer&#39;s call (2026-09-22) was to <strong>show real photographs instead</strong> — a media library is browsed by eye, and a column of identical grey boxes tests nothing about the one thing this screen is for.</p><p><strong>Lorem Picsum, because the repo already uses it.</strong> The Orders avatars are <code>https://picsum.photos/seed/&lt;seed&gt;/96</code>, so this follows the same host rather than introducing a second one; Picsum serves real Unsplash photographs. The seed is the <strong>item code</strong>, so each row gets a stable, distinct picture across reloads — which matters here more than on most screens, because twelve of the fifty rows are near-duplicate screenshots taken minutes apart and telling them apart is exactly the thumbnail&#39;s job. Requested at 128 for a 64px box, so it stays sharp on a 2x display.</p><p><strong>Photos go on image and video rows; audio and documents keep a glyph.</strong> Not a shortcut — it is the same conclusion the live screen reaches, whose <code>MediaTypeAR</code> gives those families a format icon rather than a picture. A PDF has no thumbnail to show.</p><p><code>object-fit: cover</code>, not <code>contain</code>: the box is square and the sources are not, and letterboxing fifty mixed aspect ratios turns an even column into a ragged one. The background stays underneath as the loading and failure state. <code>alt</code> is <strong>empty on purpose</strong> — the Title column sits immediately beside the image and already names the item, so an alt would make a screen reader read every row&#39;s name twice.</p><p>The seam for the real thing is <code>row.thumbUrl</code>: point it at the real asset and nothing else changes. <code>TODO(backend:Listing) media-thumbnails</code>.</p><h2 id="type-four-glyphs-instead-of-thirty" tabindex="-1">Type: four glyphs instead of thirty <a class="header-anchor" href="#type-four-glyphs-instead-of-thirty" aria-label="Permalink to &quot;Type: four glyphs instead of thirty&quot;">​</a></h2><p>Live picks one of 30 bespoke 40×40 format icons out of a 49-slot array keyed on <code>DocMimeTypeCode</code> — and <strong>19 of those slots are empty strings</strong>, so those rows render nothing at all. This shows one of four Lucide family glyphs plus the format in words (designer, 2026-09-22).</p><p>The families are not invented. <code>MediaInbox.cfm</code>&#39;s own <code>&lt;cfswitch&gt;</code> already groups the same mimetype codes into exactly Image / Video / Audio / Document for the Media Type filter:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Image     4,5,14,44,50</span></span>\n<span class="line"><span>Video     2,8,11,18,20,21,22,24,25,26,27,30,37,41,48</span></span>\n<span class="line"><span>Audio     9,13,19,23</span></span>\n<span class="line"><span>Document  15,16,17,29,33,34,40,42,45,46,47,49</span></span></code></pre></div><p>So the column reads <code>image JPEG</code>, <code>file-text PDF</code>, <code>video MP4</code> — the family from a grouping the screen already makes, the format from the mimetype.</p><h2 id="title-searches-three-fields" tabindex="-1">Title searches three fields <a class="header-anchor" href="#title-searches-three-fields" aria-label="Permalink to &quot;Title searches three fields&quot;">​</a></h2><p>The live query LIKEs the term against <code>MediaItem.Name</code> <strong>or</strong><code>MediaFileItem.FileName</code>, and matches <code>MediaItemCode</code> outright when the term is numeric. The filename is the one that matters: every display name in this library is a tidied screenshot (&quot;Screenshot 2023-09-01 at 11.15.17&quot;) while the file underneath keeps the original.</p><p><code>scopeFields</code> with <strong>no</strong> <code>scopedBy</code> is now a fixed multi-field text match — the generalisation of the Article Archive mechanism, where a chip picked the fields. Measured: a filename-only term finds its row, an item code finds its row, a display-name term finds two.</p><h2 id="sorting-the-third-different-answer-in-four-screens" tabindex="-1">Sorting: the third different answer in four screens <a class="header-anchor" href="#sorting-the-third-different-answer-in-four-screens" aria-label="Permalink to &quot;Sorting: the third different answer in four screens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Sorting</th></tr></thead><tbody><tr><td>Orders</td><td><code>hs</code> whitelisted to seven values</td></tr><tr><td>Articles</td><td>no whitelist — anything sent is interpolated into the ORDER BY</td></tr><tr><td>Article Archive</td><td>whitelisted to seven <code>&lt;cfswitch&gt;</code> cases</td></tr><tr><td>Media Items</td><td><strong>none at all</strong> — <code>headerSort = &quot;&quot;</code></td></tr></tbody></table><p>So not one column here carries a <code>sort</code> token. The order is fixed at <code>sOrderBy = &quot;PublishStart&quot;</code> DESC, and PublishStart is not one of the six columns, so — as on Article Archive — the screen opens on an order no header can claim.</p><h2 id="two-of-sixteen-are-not-filters" tabindex="-1">Two of sixteen are not filters <a class="header-anchor" href="#two-of-sixteen-are-not-filters" aria-label="Permalink to &quot;Two of sixteen are not filters&quot;">​</a></h2><ul><li><strong>Media Per Screen</strong> (<code>LimitBy</code>, 25/50/100/200/500) is the toolbar&#39;s page size. Same call as Articles&#39; Articles Per Screen.</li><li><strong>Layout</strong> (<code>MediaLayOut</code>, Grid/Listing) is the view switch, and the Grid half is the next screen — a chip that swaps to a view that does not exist would be a dead control. Note <strong>the live default is Grid</strong>, not Listing; the URL this was built from forces <code>MediaLayOut=Listing</code>. <code>TODO(backend:Listing) media-layout-switch</code>.</li></ul><h2 id="the-fourth-per-screen-value-found-in-a-shared-place" tabindex="-1">The fourth per-screen value found in a shared place <a class="header-anchor" href="#the-fourth-per-screen-value-found-in-a-shared-place" aria-label="Permalink to &quot;The fourth per-screen value found in a shared place&quot;">​</a></h2><p>Page size is 25 here — the only one of the four not defaulting to 20 — and that is how it surfaced that the toolbar&#39;s page-size <strong>label</strong> is static markup reading <code>20</code>, updated only on change. Every screen so far happened to open on 20, so it never showed; Media Items rendered 25 rows under a control claiming 20. Now set from the config at init.</p><p>That makes four, and the pattern is worth acting on rather than re-discovering:</p><table tabindex="0"><thead><tr><th>What</th><th>Where it was living</th><th>How it surfaced</th></tr></thead><tbody><tr><td>Row identity (<code>orderNo</code>)</td><td>hard-coded in the renderer</td><td>blank aria-labels on Articles</td></tr><tr><td>Export</td><td>markup in the cloned template</td><td>designer</td></tr><tr><td>Kebab actions</td><td>Figma content on the shared FilterBar frame</td><td>designer</td></tr><tr><td>Page-size label</td><td>static <code>20</code> in the shared markup</td><td>a screen that opens on 25</td></tr></tbody></table><h2 id="next-the-grid-view" tabindex="-1">Next: the Grid view <a class="header-anchor" href="#next-the-grid-view" aria-label="Permalink to &quot;Next: the Grid view&quot;">​</a></h2><p>The other half of <code>MediaLayOut</code>. Live renders it through <code>MediaLightbox.cfm</code> rather than <code>ListForm.cfm</code>, so it is a genuinely different rendering of the same query and the same filter catalogue — not a column variation. The filters, the page size and the row data built here are all reusable as-is; what is new is the card and the layout switch.</p><h2 id="spare-width-is-shared-not-dumped-on-the-main-column" tabindex="-1">Spare width is shared, not dumped on the main column <a class="header-anchor" href="#spare-width-is-shared-not-dumped-on-the-main-column" aria-label="Permalink to &quot;Spare width is shared, not dumped on the main column&quot;">​</a></h2><p>Designer, 2026-09-22, across all four screens. Under fixed layout the fit gave every column its measured width and then handed <strong>all</strong> the leftover to the single fluid column. At a 555px Media Items table that produced a <strong>331px Title beside a 78px Type</strong> — the title&#39;s own text ran out long before its column did, so the row read as one wide column and then a huddle on the right.</p><p><code>shareSpare()</code> now hands the surplus out in <strong>equal shares</strong> to the columns that can use it, and the fluid column absorbs only what is left.</p><p><strong>Equal, not proportional.</strong> Proportional shares keep the widest column widest, which is the thing being complained about.</p><p><strong><code>hug</code> columns stay out of it.</strong> They are shrink-wrapped by role — a date, an ID, a count — and their content is a fixed shape that gains nothing from more room. Only the fluid column and the <code>snug</code> ones grow.</p><p><strong>Water-filling, because <code>snug</code> has a ceiling.</strong> Everyone takes an equal slice; anyone who reaches <code>SNUG_MAX</code> takes only what fits and drops out; the rest is shared again among those still growing. At most one pass per column. The fluid column has no ceiling, so there is always somewhere for the remainder to go — which is what keeps the widths summing to the table exactly, with no gap at the right-hand edge.</p><h3 id="the-first-attempt-made-the-main-column-the-narrowest" tabindex="-1">The first attempt made the main column the narrowest <a class="header-anchor" href="#the-first-attempt-made-the-main-column-the-narrowest" aria-label="Permalink to &quot;The first attempt made the main column the narrowest&quot;">​</a></h3><p>Worth recording because it looked right in the code and was obviously wrong on screen. The fluid column&#39;s base was <code>FLUID_MIN</code> (192) while every other column based on its measured natural width, so sharing equally <em>on top of that</em> left Media Items with a <strong>193px Title beside a 216px Section</strong>. Equal shares are only fair if everyone starts from the same kind of number.</p><p>The fluid column now bases on its natural width like everything else, floored at <code>FLUID_MIN</code>. It still absorbs the rounding remainder and still gives width back first when the table is over budget; only its starting point moved.</p><h3 id="measured-before-and-after" tabindex="-1">Measured, before and after <a class="header-anchor" href="#measured-before-and-after" aria-label="Permalink to &quot;Measured, before and after&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Screen / table</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>Media Items @555</td><td>Title 331 · Type 78</td><td>Title 289 · Type 121</td></tr><tr><td>Media Items @1155</td><td>Title 283 · Type 92 · Section 192 · Created By 167</td><td>Title 265 · Type 93 · Section 192 · Created By 176</td></tr><tr><td>Orders @555</td><td>Customer took the slack</td><td>Order No 81 · Customer 267 · Order Total 126</td></tr><tr><td>Articles @555</td><td>Title took the slack</td><td>Title 278 · Section 197</td></tr></tbody></table><p>All four screens re-checked at 1600 / 1400 / 1200 / 1000 / 700 / 480 / 390 / 320: <strong>no overflow, no right-edge gap, and the same column counts as before</strong> — the change moves width between columns, never changes how many survive.</p><h1 id="media-items-·-grid-—-the-other-half-of-medialayout" tabindex="-1">Media Items · Grid — the other half of MediaLayOut <a class="header-anchor" href="#media-items-·-grid-—-the-other-half-of-medialayout" aria-label="Permalink to &quot;Media Items · Grid — the other half of MediaLayOut&quot;">​</a></h1><p>Built 2026-09-22, from <code>/AfcMediaLibrary/CC/MediaLightbox.cfm</code>. Not a new screen: it is the same query rendered differently, so it lives inside the same <code>.datatables</code> block and shares the toolbar, the page size and the pager — exactly as live does, where both layouts run through the same <code>GetMediaItems</code> call and the same <code>BrowseListBar</code>.</p><p><code>layouts: [&#39;listing&#39;, &#39;grid&#39;]</code> in the config is what puts the switch in the toolbar. The other three screens declare nothing and get no control.</p><p>The switch sits <strong>last in the toolbar&#39;s actions cluster</strong>, after Edit Columns. It started before it, which meant that in grid view — where Edit Columns is hidden, there being no columns — the switch slid <strong>135px</strong> sideways the moment you pressed it, so the control you had just clicked was no longer under the pointer (designer, 2026-09-22). Flush right, it does not move: measured 0px of travel between the two views.</p><p><strong>Icons only when the column is narrow</strong> (designer, 2026-09-22). The toolbar has to hold a page-size control, a count and this; at a 338px column the two labels are the first thing that can go without losing a function. The switch drops 162px → 83px.</p><p><code>@container</code>, matching every other responsive rule on this table — the question is how much room the CONTENT COLUMN has, and a docked SidebarMenu takes that away with no window resize. Note the threshold reads oddly against a <code>getBoundingClientRect</code>: the labels are already gone at a 808px page, because a container query measures the CONTENT box and the page&#39;s own padding and scrollbar gutter put that at ~757.</p><p>The accessible name does not change with the labels. Each button carries an <code>aria-label</code>, so hiding the span takes away the visible text and nothing else — without it, two radios would go unnamed exactly when the icons are all there is. The label wrapper is <code>.seg-control__btn-label</code>, a hook the component documents but does not style; if a second screen needs the same collapse, that is when it should become a real <code>--icon-only</code> variant of the component rather than a second contextual override.</p><p>The switch is <strong>SegmentedControl at <code>--sm</code></strong> (designer, 2026-09-22, pointing at Figma <code>2699:2052</code>). That size did not exist in the component and was built for this — see <code>SegmentedControl.figma-notes.md</code>, including three things flagged back to Figma. 32px is also what the toolbar needed: it now matches the page-size control and Edit Columns exactly, where the Default&#39;s 40 stood proud of the row. Measured: all three controls h=32, same top.</p><h2 id="what-live-actually-draws-and-what-changed" tabindex="-1">What live actually draws, and what changed <a class="header-anchor" href="#what-live-actually-draws-and-what-changed" aria-label="Permalink to &quot;What live actually draws, and what changed&quot;">​</a></h2><p>A <code>&lt;table class=&quot;gridtable&quot;&gt;</code> of <code>&lt;td width=&quot;140&quot;&gt;</code> cells, wrapped every <code>MEDIALIBRARYSLIDECOLUMNS</code> items — a per-client profile number, so the grid does not respond to its container at all and a docked sidebar simply crops it. Each cell holds <strong>a thumbnail and nothing else.</strong></p><table tabindex="0"><thead><tr><th>Live</th><th>Here</th><th>Why</th></tr></thead><tbody><tr><td>Thumbnail only; name, W×H, file size and type in a jQuery hover tooltip (<code>trailOn</code>)</td><td>Thumbnail + a caption block: name (13px semibold) over <code>format · created</code> (12px)</td><td><code>sTempName</code> is computed AND truncated in the source, then never printed. A hover tooltip cannot be reached by keyboard or read by a screen reader, and 96,000 unlabelled thumbnails is not a library you can scan (designer)</td></tr><tr><td>Fixed 140px cell, profile-driven column count</td><td><code>repeat(auto-fill, minmax(--ai-size-2, 1fr))</code></td><td>CLAUDE.md §4a — it has to reflow with the content column, not the window. 160px against live&#39;s off-scale 140, so the name has room to be read</td></tr><tr><td>Permanent &quot;Select all&quot; above, permanent Move/Delete row below</td><td>One selection bar, shown only when something is ticked</td><td>Two pieces of chrome for a state that is usually empty</td></tr><tr><td>Checkbox / View Album / Slideshow / Edit revealed on <code>mouseenter</code> only</td><td>All four, revealed on hover, on <strong>focus</strong>, and unconditionally where there is <strong>no hover at all</strong></td><td>A hover-only control is unreachable by keyboard AND by finger — see below</td></tr></tbody></table><h2 id="selection-is-shared-by-both-views" tabindex="-1">Selection is shared by both views <a class="header-anchor" href="#selection-is-shared-by-both-views" aria-label="Permalink to &quot;Selection is shared by both views&quot;">​</a></h2><p>Designer&#39;s call. The live Grid has Select all and a Move/Delete action row; the Listing&#39;s own row checkboxes render and do nothing at all. Two views of one screen disagreeing about whether selection means anything is the bug, not a feature.</p><p><code>SELECTED</code> is module state next to <code>ROW_ID</code>, for the same reason: the CELL renderers are pure functions of a row and cannot reach <code>config</code>. Ticking a row in the table updates its grid card and vice versa, without a re-render — a full re-render would lose scroll position mid-click. Measured: tick a table row → the grid card for the same id comes back checked and card-selected; tick a second from the grid → &quot;2 items selected&quot;; Clear → both views empty.</p><p><code>TODO(backend:Listing) listing-bulk-actions</code> — Move and Delete are inert.</p><h2 id="the-card-s-hover-bar-is-four-controls-not-two" tabindex="-1">The card&#39;s hover bar is FOUR controls, not two <a class="header-anchor" href="#the-card-s-hover-bar-is-four-controls-not-two" aria-label="Permalink to &quot;The card&#39;s hover bar is FOUR controls, not two&quot;">​</a></h2><p>Corrected 2026-09-22 after the designer pointed at the live screen: the first build shipped a checkbox and a pencil, and <code>.MediaButtons</code> in <code>MediaLightbox.cfm</code> actually holds a checkbox and <strong>three</strong> icons.</p><table tabindex="0"><thead><tr><th>Live icon</th><th>Action</th><th>Built as</th><th>Shown</th></tr></thead><tbody><tr><td><code>MediaLibraryAlbumViewIcon</code></td><td>View Album — go to the section holding it</td><td><code>folder-open</code></td><td>always</td></tr><tr><td><code>MEDIALIBRARYSLIDESHOWICON</code></td><td>Slideshow — open it in the lightbox</td><td><code>expand</code></td><td>image rows only</td></tr><tr><td><code>MediaLibraryEditIcon</code></td><td>Edit Details</td><td><code>pencil</code></td><td>always</td></tr></tbody></table><p>All three are <strong>Button at <code>btn--icon btn--xs</code></strong> (24×24, 12px icon) and <strong>tertiary</strong>, both the designer&#39;s instruction (2026-09-22). The first build used secondary on the reasoning that these sit on a photograph and need a fill — which had it exactly backwards, and checking the resolved values rather than reasoning from the names would have caught it:</p><table tabindex="0"><thead><tr><th></th><th><code>bg</code> base</th><th><code>bg</code> cc-light</th><th><code>bg</code> cc-dark</th></tr></thead><tbody><tr><td><code>btn--secondary</code></td><td><code>rgba(0,0,0,0)</code></td><td><code>rgba(0,0,0,0)</code></td><td><code>rgba(0,0,0,0)</code></td></tr><tr><td><code>btn--tertiary</code></td><td><code>rgba(0,0,0,0)</code></td><td><code>#e7edf0</code></td><td><code>#334155</code></td></tr></tbody></table><p>So secondary was a bordered box with <strong>no fill</strong> over the picture. Tertiary is solid under the CC brand, which is what these demos run as.</p><p><strong>One collision, flagged not fixed.</strong> <code>--ai-btn-tertiary-bg</code> in cc-light is <code>#e7edf0</code> — the <em>same value</em> as <code>--ai-surface-secondary</code>, which is the empty box a non-image card shows. So on a PDF, ZIP or audio card the buttons are invisible but for their <code>--ai-shadow-2xs</code> hairline. It reads perfectly over a photograph and disappears over the ~10% of cards without one. Either the box wants <code>--ai-surface-minimal</code> instead, or those buttons want a different type; both are designer calls, so neither was taken unasked.</p><p>Live&#39;s own conditions are kept rather than showing three unconditionally. Slideshow is <code>ImageYN</code>-gated there, so a PDF and a video each get two, not three. View Album is gated to a <em>search result</em> — the item&#39;s section differing from the one being browsed — which this prototype has no Browse mode to express, so it shows always. Measured: image 3, document 2, video 2.</p><p><code>TODO(backend:Listing) media-card-actions</code> — View Album and Slideshow go nowhere; Edit shares the row route.</p><h3 id="still-not-built" tabindex="-1">Still not built <a class="header-anchor" href="#still-not-built" aria-label="Permalink to &quot;Still not built&quot;">​</a></h3><p><strong>The AI badge.</strong> <code>AIGeneratedYN</code> is a real column and live floats an AI icon top-right when it is set — but the 50 rows came from <code>affino_list_media_items</code>, which does not return that field, so marking any of them as AI-generated would be inventing data. Left out rather than guessed.</p><h3 id="a-bug-the-reference-screenshot-caught-not-the-code" tabindex="-1">A bug the reference screenshot caught, not the code <a class="header-anchor" href="#a-bug-the-reference-screenshot-caught-not-the-code" aria-label="Permalink to &quot;A bug the reference screenshot caught, not the code&quot;">​</a></h3><p>Every non-image card was drawing its family glyph in the <strong>top-left corner</strong> instead of the middle. <code>.cc-grid__media</code> centres its own children, but the glyph is a child of the LINK inside it, and the link was <code>display: block</code>. The sizing rule missed it for the same reason — it used <code>&gt;</code> against the media box, so it matched nothing and the icon was 24px only because that is Lucide&#39;s default. The link now centres its contents and the rule is a descendant one. Measured after: the glyph&#39;s centre is 0,0 from the box&#39;s centre.</p><h2 id="the-caption-is-one-block-not-two-siblings" tabindex="-1">The caption is one block, not two siblings <a class="header-anchor" href="#the-caption-is-one-block-not-two-siblings" aria-label="Permalink to &quot;The caption is one block, not two siblings&quot;">​</a></h2><p>Designer, 2026-09-22. Name and meta were siblings of the picture, so the card&#39;s single <code>gap</code> spaced all three equally and the two text lines read as two separate things rather than one caption. They now sit in <code>.cc-grid__text</code> with their own tighter gap — <code>--ai-spacing-1</code> (4px) inside, against the card&#39;s <code>--ai-spacing-3</code> (8px) between picture and text. Both steps on the scale, not numbers picked to look right, and the caption&#39;s gap is deliberately half the card&#39;s so the two lines read as one block rather than as two more children.</p><p>Name is <strong>13px semibold</strong> (<code>--ai-font-fixed-2xs</code> / <code>--ai-font-semibold</code>) over 12px regular meta, so the pair has a hierarchy of its own.</p><p><code>min-inline-size: 0</code> on the wrapper, because a flex child&#39;s automatic minimum is its content: without it the longest name would set the column&#39;s width instead of truncating to it. Verified rather than assumed — a 340px name in a 192px box still reports <code>scrollWidth &gt; clientWidth</code>, so the ellipsis survived the extra wrapper. Measured: media→text 8px, name→meta 4px.</p><h2 id="reveal-on-hover-is-a-bet-that-the-device-has-a-pointer" tabindex="-1">Reveal-on-hover is a bet that the device has a pointer <a class="header-anchor" href="#reveal-on-hover-is-a-bet-that-the-device-has-a-pointer" aria-label="Permalink to &quot;Reveal-on-hover is a bet that the device has a pointer&quot;">​</a></h2><p>Caught by the designer, 2026-09-22, and it was a real hole rather than a rough edge. The card&#39;s checkbox and pencil sat at <code>opacity: 0</code> until <code>:hover</code>, and the picture is covered by the anchor that opens the item — so on a phone the first tap navigates away and there is no second one. <strong>Nothing in the grid could be selected on a touch device</strong>, which also put the selection bar and its Move/Delete permanently out of reach there. <code>:focus-within</code> rescues the keyboard; it does nothing for a finger.</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@media</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">hover</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: none), (pointer: coarse) {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  .cc-grid__select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  .cc-grid__edit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">opacity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>An input-capability query, not a width breakpoint</strong> — this is not a question about size. A narrow desktop window still has a pointer and reveal-on-hover is right there; a tablet at 1100px does not and it is wrong. CLAUDE.md §4a names device capability as the one case a viewport-level <code>@media</code> is actually for, and a container query cannot ask this question at all.</p><p>Verified by emulating the capability rather than assuming the rule works: with a pointer, <code>(hover: none)</code> is false and both controls rest at opacity 0; under <code>--touch-events=enabled --blink-settings=primaryHoverType=1</code>, <code>(hover: none)</code> is true and both rest at opacity 1.</p><p>The Listing view was already fine: its row pencil is <code>display: inline-flex</code> at all times and only its colour changes on hover.</p><h2 id="two-things-caught-by-measuring" tabindex="-1">Two things caught by measuring <a class="header-anchor" href="#two-things-caught-by-measuring" aria-label="Permalink to &quot;Two things caught by measuring&quot;">​</a></h2><p><strong><code>.datatables__body</code> is not unique.</strong> Every multi-select-table picker renders its own <code>&lt;div class=&quot;datatables&quot;&gt;&lt;div class=&quot;datatables__body&quot;&gt;</code> (<code>ListingScreen.js</code> ~line 531), so <code>.cc-listing[data-layout=&quot;grid&quot;] .datatables__body { display: none }</code> hid the <strong>Channel and Section pickers&#39; tables</strong> whenever the screen was in grid view — a control that silently stops working in one of two views. Child combinators fix it. <code>listingTable()</code> already carries a comment about being caught by exactly this trap; the CSS needed the same care.</p><p><strong><code>--ai-surface-brand-contrast</code> does not exist.</strong> The Apr 2026 rename took every <code>-contrast</code> brand and status surface to <code>-soft</code>, and the focus-ring examples still quoting the old name are stale. The selection bar uses <code>--ai-surface-brand-soft</code>, which is defined per theme (<code>#d9f2f2</code> light, <code>#043840</code> dark) so the bar reads in both.</p><h3 id="and-one-that-was-not-a-bug" tabindex="-1">And one that was NOT a bug <a class="header-anchor" href="#and-one-that-was-not-a-bug" aria-label="Permalink to &quot;And one that was NOT a bug&quot;">​</a></h3><p>Reading <code>borderTopColor</code> after flipping <code>data-theme</code> returned the <strong>light</strong> value in both themes, which looked like a dark-mode failure. It is the headless transition freeze: <code>.cc-grid__media</code> transitions <code>border-color</code>, and under <code>--virtual-time-budget</code> a transition never advances, so the computed value stays at the start colour forever. With <code>transition: none</code> injected first, dark resolves to <code>#334155</code> correctly. The token itself flipped all along — reading the <em>token</em> and reading the <em>element</em> disagreed, and the token was right.</p><h2 id="where-it-goes-and-why-not-the-footer" tabindex="-1">Where it goes, and why not the footer <a class="header-anchor" href="#where-it-goes-and-why-not-the-footer" aria-label="Permalink to &quot;Where it goes, and why not the footer&quot;">​</a></h2><p>The designer asked whether bulk actions belong beneath the datatable (which is where live puts them) or folded into the footer. Neither: a dedicated bar between the toolbar and the table.</p><ul><li><strong>The Media Items grid has no table footer</strong>, so a footer-based pattern cannot serve both views of one screen.</li><li><strong>The footer has a permanent job</strong> — count and pagination. Selection is transient, so the footer would change height as rows are ticked.</li><li><strong>Scope confusion.</strong> &quot;Delete&quot; a few pixels from &quot;next page&quot; invites the question of whether it applies to the page or the selection.</li><li><strong>It crowds.</strong> Orders&#39; three selects plus a verb, in a bar that already holds a count and a pager, wrap below ~900px.</li><li>And live&#39;s own placement puts the response at the far end of a 500-row table from the <strong>select-all checkbox that starts it</strong>.</li></ul><h2 id="what-each-screen-actually-declares" tabindex="-1">What each screen actually declares <a class="header-anchor" href="#what-each-screen-actually-declares" aria-label="Permalink to &quot;What each screen actually declares&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Screen</th><th>Bulk actions</th><th>Source</th></tr></thead><tbody><tr><td><strong>Orders</strong></td><td>three selects — <em>Change Status</em> · <em>Add to List</em> · <em>Archive</em></td><td><code>OrderProcessings.cfm</code>, the <code>sShowCustomButtons</code> savecontent</td></tr><tr><td><strong>Articles</strong></td><td>one select — Copy · Move · Make Live · Make Not Live · Delete</td><td><code>v-article-listing.cfc</code> line 1: <code>this.CMethods = &quot;copy,move,delete,listmakelive,listmakenotlive&quot;</code></td></tr><tr><td><strong>Media Items</strong></td><td>one select — Move · Delete</td><td><code>MediaLightbox.cfm</code>: <code>variables.directAction = &quot;move,delete&quot;</code></td></tr><tr><td><strong>Article Archive</strong></td><td><strong>none</strong></td><td><code>ArchiveManagementDef.cfm</code>: <code>CMethods = &quot;list,change,viewonly&quot;</code></td></tr></tbody></table><h3 id="selects-and-an-apply-not-rows-of-buttons" tabindex="-1">Selects and an Apply, not rows of buttons <a class="header-anchor" href="#selects-and-an-apply-not-rows-of-buttons" aria-label="Permalink to &quot;Selects and an Apply, not rows of buttons&quot;">​</a></h3><p>The first cut rendered verbs as buttons — five of them on Articles — and that was wrong twice over (designer, 2026-09-22). It wrapped to four rows on a phone, and a row of five equal-weight buttons gives no clue that Delete is not Copy. One select costs a single tap to open and reads the same at every width: Articles&#39; bar went from <strong>173px to 93px</strong> at a 338px column.</p><p>It is also what live does. <code>directAction</code> renders as a select of verbs beside an <strong>Action</strong> submit; Orders simply adds two more selects alongside it. So the uniform shape — <em>n</em> selects plus one commit button — is the live model, not a departure from it.</p><p><strong>Apply is disabled until something is chosen.</strong> The entire point of a commit button is that the destructive step is deliberate; one that is always live is just a second click. And a single Apply can carry every set select at once, which is what live&#39;s one submit does — change status <em>and</em> add to a list <em>and</em> archive in one request.</p><p><strong>The label repeats as the first menu row</strong>, which is how the live selects work (<code>&lt;option value=&quot;&quot;&gt;Change Status&lt;/option&gt;</code> heads each one). Picking it again is how you unset, and that is the only way back to &quot;nothing chosen&quot; once a value is showing.</p><h3 id="select-all-lives-in-the-table-header" tabindex="-1">Select all lives in the table header <a class="header-anchor" href="#select-all-lives-in-the-table-header" aria-label="Permalink to &quot;Select all lives in the table header&quot;">​</a></h3><p>Designer, 2026-09-22. The <code>select</code> column&#39;s header cell carries the box, with <strong>no visible label</strong> — the column is a checkbox column and the header is a checkbox; the name is on the input for a screen reader. It ticks every row on the <strong>current page</strong>, which is what a header checkbox means in a paged table, and unticks itself the moment any row is unticked.</p><p>A screen with no bulk actions has no select column, so this cannot appear anywhere selection would lead nowhere: Orders, Articles and Media Items have one; Article Archive does not.</p><p><strong>No indeterminate state.</strong> A partially selected page shows the header box unchecked. Checkbox has no Figma variant for a dash glyph and inventing one is not this change&#39;s to make — flagged rather than faked.</p><p><strong><code>data-listing-select-all</code>, not <code>data-select-all</code>.</strong> FilterDropdowns already owns that name for the multi-select-table pickers&#39; own header box, so the first cut had ticking the Section picker&#39;s select-all also tick every row in the table behind it. The lookups are scoped to <code>[data-listing-head]</code> for the same reason. Verified both ways: the header box ticks 20/20 table rows and none of the picker&#39;s; the picker&#39;s ticks its own 11 and leaves the table at 0.</p><blockquote><p><strong>Third time a non-unique hook has bitten this template</strong> — after <code>.datatables__body</code> (every multi-select-table picker renders its own) and <code>orderNo</code> (row identity hard-coded in a shared renderer). The pattern is a name that reads as specific inside one component and is not, once two components share a DOM. Check a hook is free before reusing it, and scope the lookup even when it looks unambiguous.</p></blockquote><h3 id="the-bar-s-actions-take-their-own-line-on-a-narrow-column" tabindex="-1">The bar&#39;s actions take their own line on a narrow column <a class="header-anchor" href="#the-bar-s-actions-take-their-own-line-on-a-narrow-column" aria-label="Permalink to &quot;The bar&#39;s actions take their own line on a narrow column&quot;">​</a></h3><p>Designer, 2026-09-22. They were wrapping under the count but keeping <code>margin-inline-start: auto</code>, so the select hung off to the right with a ragged gap beneath &quot;2 items selected&quot; — two half-rows reading as one broken one. Below the container&#39;s 767px the cluster gets <code>flex-basis: 100%</code> and loses the auto margin, so the break is deliberate and the row starts where the count does. Measured on all three: right-aligned and inline at 1600, left-aligned on its own line from ~1200 down, no table overflow at any width.</p><p>And it becomes a <strong>two-column grid</strong> down there rather than a wrapping flex row (designer, 2026-09-22). Orders&#39; three selects plus Apply made a 3-then-1 row that left a half-empty last line; a grid pairs them 2×2, and Articles&#39; single select plus Apply gets one even row. <code>minmax(0, 1fr)</code> rather than <code>1fr</code>, so a long option label cannot push a column past its share — and the selects&#39; 160px cap comes off, because in a grid cell it would leave the control short of its own column.</p><p>The bar&#39;s inline padding also tightens from <code>--ai-spacing-5</code> to <code>--ai-spacing-4</code> below the breakpoint, matching the narrower gutters the rest of the table uses there; block padding is unchanged. Measured: 8/16 above, 8/12 below.</p><p><strong>Clearing the selection resets the selects.</strong> Leaving &quot;Delete&quot; sitting in a select after the rows it applied to have gone is an accident waiting for the next tick.</p><p>Orders&#39; option lists are real too: the sixteen statuses it already had, the <code>OrderList</code> table&#39;s own rows, and <code>variables.ArchiveOptions</code> (line 600) = <code>[&quot;Archive&quot;,&quot;Unarchive&quot;]</code>. Twelve of the twenty order lists are called &quot;Cats list&quot; — kept, because an operator picking from that menu is exactly why a list picker needs more than a name, and a tidied demo hides it.</p><h3 id="the-bar-sticks-under-the-cc-header" tabindex="-1">The bar sticks under the CC header <a class="header-anchor" href="#the-bar-sticks-under-the-cc-header" aria-label="Permalink to &quot;The bar sticks under the CC header&quot;">​</a></h3><p>Designer, 2026-09-23. Select-all lives in the table head, so ticking a row far down the page produced a bar that had already scrolled away above you — the actions existed and could not be reached without scrolling back up. The bar is now <code>position: sticky</code> and pins to the underside of the CC header while any part of the table is still on screen; scroll past the table&#39;s end and it goes with it rather than floating over the page. It works in the Media Items grid view too, since the grid sits inside the same <code>.datatables</code>.</p><ul><li><strong><code>.datatables</code> had to become <code>overflow: clip</code>.</strong> With <code>hidden</code> it was a scroll container, the sticky stuck to it, and it never scrolls — nothing moved. <code>clip</code> clips the rounded corners identically and creates no scroll container. <code>hidden</code> is kept first as a fallback. See Datatables&#39; notes.</li><li><strong>The offset is NEGATIVE — the page&#39;s own top padding.</strong> A sticky is inset by its scroller&#39;s padding, so <code>top: 0</code> pinned it 24px below the header with rows showing through the gap (measured). <code>-spacing-6</code>, and <code>-spacing-4</code> below a 768px viewport, mirroring <code>.cc-control__page</code>&#39;s padding on the same viewport <code>@media</code>. Keep the two in step.</li><li><strong><code>--ai-shadow-sm</code> only while pinned</strong> (designer&#39;s choice over a border-only version). CSS cannot tell a stuck sticky from a resting one, so <code>watchSelectionStuck</code> in ListingScreen.js compares the bar&#39;s top with the scroller&#39;s edge on scroll, on a scroller resize and whenever the bar is shown or hidden, and toggles <code>.cc-listing__selection--stuck</code>.</li><li><strong>z-index 1</strong> — above the rows (no row control sets one), below any open dropdown or select panel (10/11).</li></ul><p>Measured in headless Chrome at 1400 and 600 wide: pinned exactly on the scroller&#39;s edge (0.0px), <code>--stuck</code> set while pinned, cleared at the top of the page, and <code>elementFromPoint</code> at the bar&#39;s centre lands inside the bar.</p><p><strong>The rows hold still when the bar appears or goes.</strong> The bar is in flow above the table, so showing it pushes everything below down by its height (49px at 1400, 133px at 600 where it wraps). Chrome&#39;s CSS scroll anchoring already absorbs that; <code>holdScrollAcross</code> in ListingScreen.js covers browsers that do not anchor, by measuring how far the content below the bar actually moved and scrolling by the same amount — so it never double-corrects. It only acts when the bar&#39;s slot is above the viewport; with the table&#39;s top on screen the bar appearing in place is the intended reveal. Measured with <code>overflow-anchor: none</code> forced: 49px without it, 0 with it, on tick and on Clear, at both widths.</p><p><strong>A probe trap worth keeping.</strong> A first measurement reported a 49px jump in Chrome. It was the hidden checkbox INPUT being measured: it is absolutely positioned and sat 427px below its own row, so its rect does not follow the row. Measure the <code>tr</code>, never the visually hidden input.</p><h3 id="the-table-header-sticks-too" tabindex="-1">The table header sticks too <a class="header-anchor" href="#the-table-header-sticks-too" aria-label="Permalink to &quot;The table header sticks too&quot;">​</a></h3><p>Designer, 2026-09-23. The column header pins under the CC header — or, with rows ticked, directly under the pinned selection bar — so the column names and Select-all stay in view while scrolling a long page.</p><ul><li><strong><code>.datatables__body</code> is <code>overflow-x: clip</code> on the listing</strong> (Datatables keeps <code>auto</code> everywhere else). <code>auto</code> made the body a scroll container and a sticky header inside it stuck to the body, which never scrolls vertically. Safe only because the column fit keeps the table inside its body: measured on all three listing screens at 320, 390, 600, 768, 1024, 1280, 1600 and 1920 — horizontal overflow 0 in all 24. A column set that could overflow would now be clipped, not scroll; revisit this first if that changes.</li><li><strong>Sticky on the <code>th</code> cells, with the line and shadow drawn by <code>th::after</code>.</strong> With <code>border-collapse: collapse</code> the table paints the cell border, so it stays behind when the cell moves, and <code>box-shadow</code> does not apply to cells in that model. While stuck, a pseudo-element the full height of each cell draws the header&#39;s line (<code>--ai-datatable-table-border</code>) and casts <code>--ai-shadow-sm</code>. Each overhangs its neighbours by spacing-4 and is clip-pathed back to its own cell, top and sides, so only the shadow below shows and the pieces tile into one edge with no notch at the column seams.</li><li><strong>The shadow first never appeared</strong> (&quot;we need a shadow&quot;). The state rule <code>.cc-listing__head--stuck th::after</code> scored (0,1,2) against the base rule&#39;s (0,2,2) and always lost, so opacity stayed 0 with the class set. Now <code>.cc-listing [data-listing-head].cc-listing__head--stuck th::after</code>. Verified both ways: opacity 1 with the fix, 0 with only the old selector restored. Note for probing: a pseudo-element&#39;s transition is not stopped by an inline <code>transition: none</code> on its element, and transitions never advance under headless virtual time — inject <code>*::after { transition: none !important }</code>.</li><li><strong>The offset clears the bar</strong>, whose height is 49px, 133px when it wraps, or 0 with nothing ticked — measured into <code>--cc-listing-bar-h</code> on the listing root, synchronously when the bar shows or hides and on any resize of it.</li><li><strong>One shadow, at the bottom of the stack.</strong> Header stuck → the header has it and the bar drops its own; the bar takes it back if the header leaves first.</li><li><strong>z-index:</strong> bar 2, header 1, so the bar&#39;s select menus open over the pinned header (hit-tested) and rows scroll under both.</li></ul><p>Measured at 1400 and 600: header 0.0px from the edge with nothing ticked; bar at 0 and header exactly one bar-height below (49 / 133) when ticked; rows still 0px on tick; nothing stuck at the top of the page. Screenshots checked in light and dark.</p><h3 id="sticky-on-every-listing-screen-—-verified-per-screen" tabindex="-1">Sticky on every listing screen — verified per screen <a class="header-anchor" href="#sticky-on-every-listing-screen-—-verified-per-screen" aria-label="Permalink to &quot;Sticky on every listing screen — verified per screen&quot;">​</a></h3><p>2026-09-23. No per-screen work was needed: all four pages load the shared ListingScreen.css / .js and carry <code>.cc-listing</code>, <code>[data-listing-head]</code> and <code>[data-listing-selection]</code>, so the sticky bar and header came with the shared code. Measured in headless Chrome rather than assumed:</p><table tabindex="0"><thead><tr><th>Screen</th><th>Header, nothing ticked</th><th>Row ticked</th><th>Rows move on tick</th></tr></thead><tbody><tr><td>Orders, 1400 / 600</td><td>0.0px, shadow on</td><td>bar 0, header +49 / +133</td><td>0px</td></tr><tr><td>Articles, 1400 / 600</td><td>0.0px, shadow on</td><td>bar 0, header +49 / +93</td><td>0px</td></tr><tr><td>Media Items list, 1400 / 600</td><td>0.0px, shadow on</td><td>bar 0, header +49 / +93</td><td>0px</td></tr><tr><td>Media Items grid, 1400</td><td>no header in grid</td><td>bar pins at 0 with its shadow</td><td>cards 0px</td></tr><tr><td>Article Archive, 1400 × 420</td><td>0.0px, shadow on</td><td>no selection on this screen</td><td>—</td></tr></tbody></table><p>Nothing is pinned at the top of the page on any screen. Article Archive has 16 rows, so an 800px-tall window cannot scroll far enough to pin anything; it was measured in a 420px-tall one. <strong>A new listing screen gets this for free only if it keeps those three hooks and the <code>.cc-control__page</code> scroller</strong> — see the backend handover (<code>docs/listing-screens-handover.md</code>).</p><h3 id="every-screen-gets-a-record-link-—-link-true" tabindex="-1">Every screen gets a record link — <code>link: true</code> <a class="header-anchor" href="#every-screen-gets-a-record-link-—-link-true" aria-label="Permalink to &quot;Every screen gets a record link — `link: true`&quot;">​</a></h3><p>2026-09-23, found while writing the backend handover. Only Orders had a way into a record: its <code>order</code> cell renders the <code>[data-row-link]</code> anchor that the whole-row click follows. Articles, Article Archive and Media Items had no such column, so their rows did nothing when clicked and offered no keyboard route — yet still got the pointer cursor and hover tint, because the class was added unconditionally. Measured: 0 row links, <code>cursor: pointer</code>, on all three.</p><ul><li><strong><code>link: true</code> on a column</strong> wraps its content in the same anchor (<code>a.datatables__record-link[data-row-link]</code>, <code>ROUTE.view</code> href, marker <code>listing-row-routes</code>). Set on <strong>Title</strong> on all three screens — each one&#39;s identity column, as the order number is on Orders. It goes inside the truncate span, so long titles still clip with an ellipsis. Text-like cells only: an anchor must not wrap a chip (a button) or another link. The detail row does not repeat it.</li><li><strong><code>datatables--rows-clickable</code> is now added only when the screen declares a record link</strong> (<code>type: &#39;order&#39;</code> or <code>link: true</code>). A screen without one gets rows that do not look clickable — the &quot;never advertise an affordance&quot; rule, now enforced rather than assumed.</li><li>Styled with the order link: the cell&#39;s own colour, underline on hover and focus (Datatables.css).</li></ul><p>Verified in headless Chrome: one link per row on all four screens (20 / 20 / 8 / 25); clicking a non-control part of a row opens that row&#39;s record at 1400 and 390 wide; titles still clip (11 of 20 at 390, 9 of 20 at 1400) with the link inline inside the ellipsis span; link colour equals the cell&#39;s.</p><h2 id="article-archive-loses-its-checkbox-column" tabindex="-1">Article Archive loses its checkbox column <a class="header-anchor" href="#article-archive-loses-its-checkbox-column" aria-label="Permalink to &quot;Article Archive loses its checkbox column&quot;">​</a></h2><p>It has nothing a selection could be <strong>for</strong>. So no bar, and the template drops the <code>select</code> column with it — a checkbox that can lead nowhere is precisely the dead control this bar exists to end, and the same complaint that started the whole exercise (the Listing view&#39;s checkboxes doing nothing while the Grid&#39;s did something). One column fewer at every width; re-measured, no overflow.</p><h2 id="details-worth-keeping" tabindex="-1">Details worth keeping <a class="header-anchor" href="#details-worth-keeping" aria-label="Permalink to &quot;Details worth keeping&quot;">​</a></h2><ul><li><strong>Clear sits with the count, not among the actions.</strong> It dismisses a state rather than doing something to the rows, and on Articles&#39; five-verb bar it was stranding itself on a second line.</li><li><strong><code>white-space: nowrap</code> on the count</strong> — &quot;2 items selected&quot; was wrapping to two lines and making the bar taller than the row it describes.</li><li><strong>The whole BAR wraps, not just the actions inside it.</strong> With only the inner row wrapping, the count and Clear held their line and the three 160px selects had nowhere to go — 34px of overflow at a 309px table, which dragged the datatable wider than its column. The selects&#39; 160px is a <strong>cap, not a floor</strong> (<code>flex: 0 1</code> + <code>min-inline-size: 0</code>), so they give way on a phone.</li><li><strong><code>flex: 1 1 auto</code> on the action cluster</strong>, not the default <code>0 1 auto</code>. A wrapping flex container that is itself a flex item sizes to its min-content, so the moment the selects became shrinkable the cluster collapsed to ~341px and wrapped to two rows <em>at 1600</em>, where it had been one. Caught by re-measuring the wide end after fixing the narrow one.</li><li>Measured, both bars: one row to ~1200, then 2, then 3 at 390 and 4 for Articles&#39; five verbs at 320. No overflow at any width.</li><li><strong>Select.js needs no re-init.</strong> It binds one delegated click listener at the document, so a select rendered into the bar after load works — verified by opening one and picking from it, not assumed.</li><li><strong>Background is <code>--ai-datatable-table-expanded-bg</code></strong> (designer), not a brand wash: the bar is a <em>state of the table</em>, the same way an expanded row is, and should read as the table reacting rather than a notice pasted over it. Themed — <code>#f3f6f7</code> cc, <code>#293548</code> cc-dark.</li></ul><p><code>TODO(backend:Listing) listing-bulk-actions</code> — nothing is wired. Live pairs Orders&#39; three selects with an Action submit; here each applies on pick, one step instead of two for the same outcome.</p><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3644-125909" target="_blank" rel="noreferrer">Open in Figma</a></p>',594))])}const k=i(c,[["render",u]]);export{v as __pageData,k as default};
